func openDirectoryNoFollow(path string, mode uint32) (int, error) {
	if !filepath.IsAbs(path) || filepath.Clean(path) != path || path == "/" {
		return -1, fmt.Errorf("runtime directory %q is not clean and absolute", path)
	}
	fd, err := unix.Open("/", unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC, 0)
	if err != nil {
		return -1, err
	}
	for _, name := range strings.Split(path[1:], "/") {
		if err := unix.Mkdirat(fd, name, mode); err != nil && !errors.Is(err, unix.EEXIST) {
			unix.Close(fd)
			return -1, err
		}
		next, err := unix.Openat(fd, name, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
		unix.Close(fd)
		if err != nil {
			return -1, fmt.Errorf("open %s without following symlinks: %w", path, err)
		}
		fd = next
	}
	return fd, nil
}

func clearDirectory(fd int) error {
	dup, err := unix.Dup(fd)
	if err != nil {
		return err
	}
	dir := os.NewFile(uintptr(dup), "")
	names, err := dir.Readdirnames(-1)
	dir.Close()
	if err != nil {
		return err
	}
	for _, name := range names {
		err := unix.Unlinkat(fd, name, 0)
		if errors.Is(err, unix.EISDIR) {
			child, openErr := unix.Openat(fd, name, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
			if openErr != nil {
				return openErr
			}
			err = clearDirectory(child)
			unix.Close(child)
			if err == nil {
				err = unix.Unlinkat(fd, name, unix.AT_REMOVEDIR)
			}
		}
		if err != nil {
			return err
		}
	}
	return nil
}

func SystemctlRestart(ctx context.Context, unit string) error {
	return systemctl(ctx, "--no-block", "restart", unit)
}

func systemctl(ctx context.Context, args ...string) error {
	output, err := exec.CommandContext(ctx, "systemctl", args...).CombinedOutput()
	if err != nil {
		return fmt.Errorf("systemctl %s: %w: %s", strings.Join(args, " "), err, strings.TrimSpace(string(output)))
	}
	return nil
}

func (c command) installCurrentNetBirdAgent(layout selfupdate.Layout, systemd, unit string) error {
	// Packaged worker and enrollment units execute the image's default release tree.
	if layout.Root != selfupdate.DefaultRoot {
		return fmt.Errorf("managed NetBird units require --root %s; configured root is %s", selfupdate.DefaultRoot, layout.Root)
	}
	current, err := layout.Current()
	if err != nil {
		return err
	}
	if err := layout.VerifyRelease(current); err != nil {
		return err
	}
	_, hostConfigErr := os.Stat("/etc/terrascale-orchestrator/host.json")
	start := systemd == "/etc/systemd/system" &&
		(unit == selfupdate.HostUnit || unit == selfupdate.ControllerUnit) && hostConfigErr == nil
	return c.installNetBirdAgent(layout.BinaryPath(current), systemd, start)
}

func (c command) installNetBirdAgent(binary, systemd string, start bool) error {
	// The baked fallback can run prepare while an older current release
	// still owns ExecStart. Do not add its Wants dependency until it supports the worker.
	ctx, cancel := context.WithTimeout(c.ctx, 5*time.Second)
	defer cancel()
	probe := exec.CommandContext(ctx, binary, "netbird", "agent", "run", "--help")
	probe.WaitDelay = time.Second
	if output, err := probe.CombinedOutput(); err != nil {
		if ctx.Err() != nil {
			return fmt.Errorf("probe NetBird worker support: %w", ctx.Err())
		}
		var exit *exec.ExitError
		if errors.As(err, &exit) && exit.ExitCode() >= 0 {
			slog.DebugContext(ctx, "self-update current release does not support the NetBird worker", "binary", binary,
				"error", err, "output", strings.TrimSpace(string(output)))
			return nil
		}
		return fmt.Errorf("probe NetBird worker support: %w: %s", err, strings.TrimSpace(string(output)))
	}
	_, err := selfupdate.InstallNetBirdAgent(systemd)
	if err != nil || !start {
		return err
	}
	if _, err := os.Stat(filepath.Join(systemd, selfupdate.HostSetupUnit)); errors.Is(err, os.ErrNotExist) {
		return nil
	} else if err != nil {
		return err
	}
	// Retry reload even when a previous failed or interrupted prepare wrote every file.
	if err := systemctl(c.ctx, "daemon-reload"); err != nil {
		return err
	}
	if err := systemctl(c.ctx, "enable", selfupdate.NetBirdAgentUnit); err != nil {
		return err
	}
	return c.restart(c.ctx, selfupdate.NetBirdAgentUnit)
}

func run(ctx context.Context, args []string, output io.Writer, now func() time.Time, restart Restarter) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	writer := commandio.NewWriter(output)
	if len(args) == 0 || args[0] == "--help" || args[0] == "-h" || args[0] == "help" {
		_, err := io.WriteString(writer, usage)
		return errors.Join(err, writer.Err())
	}
	c := command{ctx: ctx, output: writer, now: now, restart: restart}
	var err error
	switch args[0] {
	case "check-accepted-identity":
		err = checkAcceptedIdentity(os.Stdin, args[1:])
	case "prepare":
		err = c.prepare(args[1:])
	case "watchdog":
		err = c.watchdog(args[1:])
	case "stage":
		err = c.stage(args[1:])
	case "activate":
		err = c.activate(args[1:])
	case "status":
		err = c.status(args[1:])
	default:
		err = fmt.Errorf("unknown selfupdate command %q", args[0])
	}
	return errors.Join(err, writer.Err())
}

func (p proofFlags) check(root, unit string) (selfupdate.ProofCheck, error) {
	if *p.config != "" {
		if *p.file != "" || *p.key != "" {
			return selfupdate.ProofCheck{}, errors.New("--config replaces --proof-file and --proof-key-file")
		}
		file, key, err := roleProof(*p.config, root, unit)
		if errors.Is(err, os.ErrNotExist) {
			// The role is not configured on this node, so no process of
			// this unit can prove anything; deadlines still roll back.
			return selfupdate.ProofCheck{}, nil
		}
		if err != nil {
			slog.Warn("self-update role config is unusable; activations cannot be confirmed and roll back at their deadline",
				"config", *p.config, "error", err)
			return selfupdate.ProofCheck{}, nil
		}
		*p.file, *p.key = file, key
	}
	if *p.file == "" && *p.key == "" {
		return selfupdate.ProofCheck{}, nil
	}
	if *p.file == "" || *p.key == "" {
		return selfupdate.ProofCheck{}, errors.New("--proof-file and --proof-key-file are required together")
	}
	public, err := readIdentityPublicKey(*p.key)
	if err != nil {
		// An unusable key disables confirmation, never rollback: the
		// deadline logic still runs and restores the previous release.
		slog.Warn("self-update proof key is unusable; activations cannot be confirmed and roll back at their deadline",
			"key", *p.key, "error", err)
		return selfupdate.ProofCheck{File: *p.file}, nil
	}
	return selfupdate.ProofCheck{File: *p.file, PublicKey: public}, nil
}

func (c command) prepare(args []string) error {
	flags := flag.NewFlagSet("prepare", flag.ContinueOnError)
	layout := addLayout(flags)
	proof := addProof(flags)
	unit := flags.String("unit", "", "systemd unit that executes the current release")
	baked := flags.String("baked-binary", selfupdate.DefaultBakedBinary, "image-installed binary")
	systemd := flags.String("systemd-dir", "/etc/systemd/system", "unit directory that takes the node's self-update drop-ins")
	if err := parse(flags, args); err != nil {
		return err
	}
	accepted, inputs, err := controllerTrust(*unit)
	if err != nil {
		return err
	}
	rollbackOnly := false
	if accepted != nil {
		rollbackOnly, err = c.checkControllerRecovery(layout.layout(), *accepted, inputs, true, *baked)
		if err != nil {
			return err
		}
		if err := c.requireControllerCompletion(layout.layout(), *accepted, inputs); err != nil {
			if rollbackOnly {
				return err
			}
			current, currentErr := layout.layout().Current()
			good, goodErr := layout.layout().KnownGood()
			if currentErr != nil || goodErr != nil || current == "" || good == "" {
				return errors.Join(err, currentErr, goodErr)
			}
			if err := c.checkControllerRelease(layout.layout(), current, *accepted, inputs); err != nil {
				return err
			}
			if err := c.checkControllerRelease(layout.layout(), good, *accepted, inputs); err != nil {
				return err
			}
			_, printErr := fmt.Fprintf(c.output, "selfupdate prepare unit=%s held: compatible current and known-good; no effects\n", *unit)
			return printErr
		}
	}
	// The runtime secret mounts below belong to the host (TS-745).
	if layout.layout().Root == selfupdate.DefaultRoot {
		if moved, err := selfupdate.RunInHostMounts(c.ctx, c.output, os.Stderr); moved || err != nil {
			return err
		}
	}
	if !rollbackOnly && c.delegate(layout.layout(), append([]string{"prepare"}, args...)) {
		if err := c.backstopPrepare(layout.layout(), *unit); err != nil {
			return err
		}
		unlock, err := layout.layout().Lock()
		if err != nil {
			return err
		}
		defer unlock()
		if err := c.installCurrentNetBirdAgent(layout.layout(), *systemd, *unit); err != nil {
			slog.Warn("self-update could not prepare the NetBird worker", "error", err)
		}
		return nil
	}
	check, err := proof.check(*layout.root, *unit)
	if err != nil {
		return err
	}
	unlock, err := layout.layout().Lock()
	if err != nil {
		return err
	}
	defer unlock()
	accepted, inputs, err = controllerTrust(*unit)
	if err != nil {
		return err
	}
	if accepted != nil {
		if _, err := c.checkControllerRecovery(layout.layout(), *accepted, inputs, true, *baked); err != nil {
			return err
		}
		if err := c.requireControllerCompletion(layout.layout(), *accepted, inputs); err != nil {
			return err
		}
		if _, err := c.recoverControllerActivation(layout.layout(), *accepted, inputs); err != nil {
			return err
		}
	}
	outcome, err := selfupdate.Prepare(layout.layout(), *unit, *baked, check, c.now())
	if err != nil {
		return err
	}
	current, err := layout.layout().Current()
	if err != nil {
		return err
	}
	if _, err = fmt.Fprintf(c.output, "selfupdate prepare unit=%s outcome=%s current=%s\n", *unit, outcome, current); err != nil {
		return err
	}
	// The controller process cannot write its credential directory or
	// controller.json; its armed material generation installs here (TS-668).
	if *unit == selfupdate.ControllerUnit {
		material, err := installGeneration(c.now())
		if err != nil {
			return err
		}
		if material != "" {
			if _, err := fmt.Fprintf(c.output, "selfupdate prepare material-generation: %s\n", material); err != nil {
				return err
			}
		}
	}
	// A node whose image predates a drop-in gets it from the release that
	// runs this step; a failure must not stop the unit's start.
	changed := false
	for _, dropin := range []struct {
		name    string
		install func(string) (bool, error)
	}{{"host-setup", selfupdate.InstallHostSetupDropin}, {"bootstrap", selfupdate.InstallBootstrapDropin},
		{"controller-install", selfupdate.InstallControllerInstallDropin}, {"watchdog", selfupdate.InstallWatchdogLoggingDropin}} {
		if installed, err := dropin.install(*systemd); err != nil {
			slog.Warn("self-update could not install the "+dropin.name+" drop-in", "error", err)
		} else if installed {
			changed = true
			if _, err := fmt.Fprintf(c.output, "selfupdate prepare installed the %s drop-in\n", dropin.name); err != nil {
				return err
			}
		}
	}
	if err := c.installCurrentNetBirdAgent(layout.layout(), *systemd, *unit); err != nil {
		slog.Warn("self-update could not prepare the NetBird worker", "error", err)
	}
	// The drop-ins belong to other units, which read them at their next
	// start once systemd reloads.
	if changed {
		if err := daemonReload(c.ctx); err != nil {
			slog.Warn("self-update could not reload systemd; the drop-ins apply from the next boot", "error", err)
		}
	}
	// The unit's runtime secrets live in memory (TS-745); this root step
	// mounts their directories before the unit's process starts. A failure
	// must not fail prepare (the baked fallback would run instead): the host
	// agent refuses to write those secrets to disk.
	if layout.layout().Root == selfupdate.DefaultRoot {
		if err := memoryRuntime(*unit); err != nil {
			slog.Warn("self-update could not mount the runtime secrets in memory", "unit", *unit, "error", err)
		}
	}
	return nil
}

func (c command) watchdog(args []string) error {
	flags := flag.NewFlagSet("watchdog", flag.ContinueOnError)
	layout := addLayout(flags)
	proof := addProof(flags)
	unit := flags.String("unit", "", "systemd unit that executes the current release")
	if err := parse(flags, args); err != nil {
		return err
	}
	accepted, inputs, err := controllerTrust(*unit)
	if err != nil {
		return err
	}
	rollbackOnly := false
	if accepted != nil {
		rollbackOnly, err = c.checkControllerRecovery(layout.layout(), *accepted, inputs, false, "")
		if err != nil {
			return err
		}
		if err := c.requireControllerCompletion(layout.layout(), *accepted, inputs); err != nil {
			return err
		}
	}
	delegated := !rollbackOnly && c.delegate(layout.layout(), append([]string{"watchdog"}, args...))
	var check selfupdate.ProofCheck
	if !delegated {
		var err error
		if check, err = proof.check(*layout.root, *unit); err != nil {
			return err
		}
	}
	unlock, err := layout.layout().Lock()
	if err != nil {
		return err
	}
	accepted, inputs, err = controllerTrust(*unit)
	if err != nil {
		unlock()
		return err
	}
	if accepted != nil {
		if _, err := c.checkControllerRecovery(layout.layout(), *accepted, inputs, false, ""); err != nil {
			unlock()
			return err
		}
		if err := c.requireControllerCompletion(layout.layout(), *accepted, inputs); err != nil {
			unlock()
			return err
		}
		if _, err := c.recoverControllerActivation(layout.layout(), *accepted, inputs); err != nil {
			unlock()
			return err
		}
	}
	var outcome selfupdate.Outcome
	var activation selfupdate.Activation
	if delegated {
		outcome, activation, err = selfupdate.Backstop(layout.layout(), c.now())
	} else {
		outcome, activation, err = selfupdate.Watch(layout.layout(), *unit, check, c.now())
	}
	if err != nil {
		unlock()
		return err
	}
	// The rollout step runs after the check, so a slow or stuck step never
	// delays a rollback, and before the restart below serves what it owes.
	if !delegated && (*unit == selfupdate.ControllerUnit || *unit == selfupdate.HostUnit) && *proof.config != "" {
		unlock()
		c.rolloutStep(layout.layout(), *unit, *proof.config)
		if unlock, err = layout.layout().Lock(); err != nil {
			return err
		}
	}
	// A rollback leaves a restart obligation until the unit restarts, so a
	// failed systemctl call, an output error or a crash after the link moved
	// is retried by the next timer run instead of reading as idle.
	owed, err := layout.layout().RestartPending(*unit)
	unlock()
	if err != nil {
		return err
	}
	// An idle run runs every 15 s and says nothing. A pending run also repeats
	// every 15 s while an activation waits, so it is debug; rollbacks are warnings.
	if outcome != selfupdate.OutcomeIdle {
		level := slog.LevelInfo
		switch outcome {
		case selfupdate.OutcomePending:
			level = slog.LevelDebug
		case selfupdate.OutcomeRolledBack:
			level = slog.LevelWarn
		}
		slog.Log(c.ctx, level, "selfupdate watchdog", observability.ComponentKey, "selfupdate",
			"unit", *unit, "outcome", string(outcome), "activation", activation.ActivationID, "target", activation.Target)
	}
	if owed {
		if err := c.restart(c.ctx, *unit); err != nil {
			return err
		}
		unlock, err := layout.layout().Lock()
		if err != nil {
			return err
		}
		defer unlock()
		return layout.layout().ClearRestartPending(*unit)
	}
	return nil
}

func (c command) stage(args []string) error {
	flags := flag.NewFlagSet("stage", flag.ContinueOnError)
	layout := addLayout(flags)
	binary := flags.String("binary", "", "binary to stage")
	receipt := flags.String("receipt", "", "signed binary receipt or update receipt")
	delegation := flags.String("delegation", "", "root-signed release or binary update delegation")
	rootKey := flags.String("root-key", "", "offline root Ed25519 PKIX public key PEM")
	environment := flags.String("environment", "", "this node's release environment")
	cell := flags.String("cell", "", "this node's logical cell: GRU, SFO or FRA")
	architecture := flags.String("arch", runtime.GOARCH, "this node's architecture")
	if err := parse(flags, args); err != nil {
		return err
	}
	if *binary == "" || *receipt == "" || *delegation == "" || *rootKey == "" || *environment == "" {
		return errors.New("stage requires --binary, --receipt, --delegation, --root-key and --environment")
	}

func (c command) activate(args []string) error {
	flags := flag.NewFlagSet("activate", flag.ContinueOnError)
	layout := addLayout(flags)
	digest := flags.String("release", "", "staged release SHA-256")
	unit := flags.String("unit", "", "systemd unit that executes the current release")
	window := flags.Duration("proof-window", 5*time.Minute, "deadline for the new process's signed version proof")
	if err := parse(flags, args); err != nil {
		return err
	}
	accepted, inputs, gateErr := controllerTrust(*unit)
	if gateErr != nil {
		return gateErr
	}
	if accepted != nil {
		if err := c.requireControllerCompletion(layout.layout(), *accepted, inputs); err != nil {
			return err
		}
	}
	unlock, err := layout.layout().Lock()
	if err != nil {
		return err
	}
	accepted, inputs, gateErr = controllerTrust(*unit)
	if gateErr != nil {
		unlock()
		return gateErr
	}
	if accepted != nil {
		if err := c.checkControllerRelease(layout.layout(), *digest, *accepted, inputs); err != nil {
			unlock()
			return err
		}
		if err := c.requireControllerCompletion(layout.layout(), *accepted, inputs); err != nil {
			unlock()
			return err
		}
		if err := c.checkControllerTransitions(layout.layout(), *accepted, inputs, true, ""); err != nil {
			unlock()
			return err
		}
	}
	activation, err := selfupdate.Activate(layout.layout(), *digest, *unit, c.now(), *window)
	unlock()
	if err != nil {
		return err
	}
	if _, err := fmt.Fprintf(c.output, "selfupdate activated release=%s previous=%s activation=%s deadline=%s\n",
		activation.Target, activation.Previous, activation.ActivationID, activation.Deadline.Format(time.RFC3339)); err != nil {
		return err
	}
	return c.restart(c.ctx, *unit)
}

func (c command) status(args []string) error {
	flags := flag.NewFlagSet("status", flag.ContinueOnError)
	layout := addLayout(flags)
	if err := parse(flags, args); err != nil {
		return err
	}
	current, err := layout.layout().Current()
	if err != nil {
		return err
	}
	activation, pending, err := layout.layout().Pending()
	if err != nil {
		return err
	}
	if !pending {
		_, err = fmt.Fprintf(c.output, "current=%s pending=none\n", current)
		return err
	}
	_, err = fmt.Fprintf(c.output, "current=%s pending=%s target=%s previous=%s deadline=%s\n", current,
		activation.ActivationID, activation.Target, activation.Previous, activation.Deadline.Format(time.RFC3339))
	return err
}

func readSmall(path string) ([]byte, error) {
	file, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer file.Close()
	data, err := io.ReadAll(io.LimitReader(file, trust.MaxEnvelopeBytes+1))
	if err != nil {
		return nil, err
	}
	if len(data) > trust.MaxEnvelopeBytes {
		return nil, fmt.Errorf("%s is too large", path)
	}
	return bytes.TrimSuffix(data, []byte("\n")), nil
}

func readRootKeyring(path string) (trust.Keyring, error) {
	data, err := readSmall(path)
	if err != nil {
		return nil, err
	}
	block, rest := pem.Decode(data)
	if block == nil || block.Type != "PUBLIC KEY" || len(bytes.TrimSpace(rest)) != 0 {
		return nil, errors.New("root key must be one PKIX public key PEM block")
	}
	parsed, err := x509.ParsePKIXPublicKey(block.Bytes)
	if err != nil {
		return nil, err
	}
	public, ok := parsed.(ed25519.PublicKey)
	if !ok {
		return nil, errors.New("root key must be Ed25519")
	}
	return trust.ParseKeyring(public)
}

func readRolloutRole(path string) (rolloutRole, error) {
	var role rolloutRole
	file, err := os.Open(path)
	if err != nil {
		return role, err
	}
	defer file.Close()
	data, err := io.ReadAll(io.LimitReader(file, maxRoleConfigBytes+1))
	if err != nil {
		return role, err
	}
	if len(data) > maxRoleConfigBytes {
		return role, errors.New("role config is too large")
	}
	if err := json.Unmarshal(data, &role); err != nil {
		return role, err
	}
	if role.Version != roleconfig.Version {
		return role, fmt.Errorf("rollout role config requires version %d", roleconfig.Version)
	}
	if len(role.Controller.Rollouts) != 0 {
		return role, errors.New("rollout role config contains a retired rollout control")
	}
	return role, nil
}

func roleProof(path, root, unit string) (string, string, error) {
	file, err := os.Open(path)
	if err != nil {
		return "", "", err
	}
	defer file.Close()
	data, err := io.ReadAll(io.LimitReader(file, maxRoleConfigBytes+1))
	if err != nil {
		return "", "", err
	}
	if len(data) > maxRoleConfigBytes {
		return "", "", errors.New("role config is too large")
	}
	var config struct {
		Version    int `json:"version"`
		Controller struct {
			ResponseKeyFile     string `json:"response_key_file"`
			SelfUpdateProofFile string `json:"self_update_proof_file"`
			SelfUpdateRoot      string `json:"self_update_root"`
		} `json:"controller"`
		Host struct {
			IdentityKeyFile     string `json:"identity_key_file"`
			SelfUpdateProofFile string `json:"self_update_proof_file"`
			SelfUpdateRoot      string `json:"self_update_root"`
		} `json:"host"`
	}
	if err := json.Unmarshal(data, &config); err != nil {
		return "", "", err
	}
	if config.Version != roleconfig.Version {
		return "", "", fmt.Errorf("self-update role config requires version %d", roleconfig.Version)
	}
	var proof, key, configured string
	switch unit {
	case selfupdate.ControllerUnit:
		proof, key, configured = config.Controller.SelfUpdateProofFile, config.Controller.ResponseKeyFile, config.Controller.SelfUpdateRoot
	case selfupdate.HostUnit:
		proof, key, configured = config.Host.SelfUpdateProofFile, config.Host.IdentityKeyFile, config.Host.SelfUpdateRoot
	default:
		return "", "", fmt.Errorf("unit %s has no role config", unit)
	}
	if key == "" {
		return "", "", errors.New("role config names no identity key")
	}
	// The process proves activations under its own root only.
	if configured != "" && configured != root {
		return "", "", fmt.Errorf("role config self_update_root %s differs from --root %s", configured, root)
	}
	if proof == "" {
		proof = selfupdate.DefaultProofFile(root, unit)
	}
	return proof, key, nil
}

// readIdentityPublicKey derives the public key from the unit's base64
// Ed25519 identity key file, the same format the runtime loads.
func readIdentityPublicKey(path string) (ed25519.PublicKey, error) {
	info, err := os.Lstat(path)
	if err != nil {
		return nil, err
	}
	if !info.Mode().IsRegular() || info.Mode().Perm()&0o077 != 0 {
		return nil, errors.New("proof key must be a regular file readable only by its owner")
	}
	data, err := readSmall(path)
	if err != nil {
		return nil, err
	}
	decoded, err := base64.StdEncoding.DecodeString(strings.TrimSpace(string(data)))
	if err != nil || len(decoded) != ed25519.PrivateKeySize {
		return nil, errors.New("proof key must contain 64 base64 Ed25519 bytes")
	}
	return ed25519.PrivateKey(decoded).Public().(ed25519.PublicKey), nil
}

func NewLayout(root string) Layout { return Layout{Root: root, Owner: 0} }

func (layout Layout) validate() error {
	if !filepath.IsAbs(layout.Root) || filepath.Clean(layout.Root) != layout.Root || layout.Owner < 0 {
		return fmt.Errorf("%w: release root must be a clean absolute path", ErrInvalid)
	}
	return nil
}

func (layout Layout) releasesPath() string { return filepath.Join(layout.Root, releasesDir) }
func (layout Layout) currentPath() string  { return filepath.Join(layout.Root, currentLink) }
func (layout Layout) activationPath() string {
	return filepath.Join(layout.Root, activationFile)
}
func (layout Layout) knownBadPath() string { return filepath.Join(layout.Root, knownBadFile) }

// ReleaseDir is the directory of one staged release.
func (layout Layout) ReleaseDir(digest string) string {
	return filepath.Join(layout.releasesPath(), digest)
}

// BinaryPath is the executable of one staged release.
func (layout Layout) BinaryPath(digest string) string {
	return filepath.Join(layout.ReleaseDir(digest), BinaryName)
}

// CurrentExecutable is the path the systemd ExecStart line runs.
func (layout Layout) CurrentExecutable() string {
	return filepath.Join(layout.currentPath(), BinaryName)
}

// ensureDirs creates the root and releases directories with exclusive
// ownership and verifies existing ones.
func (layout Layout) ensureDirs() error {
	if err := layout.validate(); err != nil {
		return err
	}
	for _, path := range []string{layout.Root, layout.releasesPath()} {
		// The units run with UMask=0077; set the mode explicitly so the
		// unprivileged controller can traverse to its binary.
		if err := os.Mkdir(path, 0o755); err == nil {
			if err := os.Chmod(path, 0o755); err != nil {
				return err
			}
		} else if !errors.Is(err, os.ErrExist) {
			return err
		}
		if err := layout.checkOwned(path, true); err != nil {
			return err
		}
	}
	return nil
}

// checkOwned rejects symlinks, foreign owners and group or world write.
func (layout Layout) checkOwned(path string, directory bool) error {
	info, err := os.Lstat(path)
	if err != nil {
		return err
	}
	stat, ok := info.Sys().(*syscall.Stat_t)
	if !ok || int(stat.Uid) != layout.Owner || info.Mode().Perm()&0o022 != 0 ||
		directory && !info.IsDir() || !directory && !info.Mode().IsRegular() {
		return fmt.Errorf("%w: %s", ErrUnsafe, path)
	}
	return nil
}

// Current returns the digest the current link points at, or "" when the
// link is absent.
func (layout Layout) Current() (string, error) { return layout.readLink(currentLink) }

// KnownGood returns the digest the known-good link points at, or "" when
// the link is absent: the last release a unit confirmed with a version
// proof. Nothing else moves it, so a restore, an unreadable record or the
// seed never make a release that has not proved itself the delegate.
func (layout Layout) KnownGood() (string, error) { return layout.readLink(knownGoodLink) }

func (layout Layout) readLink(name string) (string, error) {
	if err := layout.validate(); err != nil {
		return "", err
	}
	target, err := os.Readlink(filepath.Join(layout.Root, name))
	if errors.Is(err, os.ErrNotExist) {
		return "", nil
	}
	if err != nil {
		return "", err
	}
	digest, ok := strings.CutPrefix(target, releasesDir+"/")
	if !ok || !digestRE.MatchString(digest) {
		return "", fmt.Errorf("%w: %s link target %q", ErrUnsafe, name, target)
	}
	return digest, nil
}

// Delegate returns the release that runs the root self-update steps in
// place of the image-baked binary: the known-good release, unless it is the
// baked one or was rejected since. "" means the baked binary runs them
// itself.
func (layout Layout) Delegate() (string, error) {
	digest, err := layout.KnownGood()
	if err != nil || digest == "" {
		return "", err
	}
	if _, err := os.Lstat(filepath.Join(layout.ReleaseDir(digest), bakedMarkerFile)); err == nil {
		return "", nil
	}
	knownBad, err := layout.KnownBad()
	if err != nil || knownBad[digest] {
		return "", err
	}
	return digest, layout.VerifyRelease(digest)
}

// VerifyRelease checks that a staged release is exclusively owned,
// read-only and that its bytes still hash to its directory name.
func (layout Layout) VerifyRelease(digest string) error {
	if !digestRE.MatchString(digest) {
		return fmt.Errorf("%w: release digest", ErrInvalid)
	}
	for _, path := range []string{layout.Root, layout.releasesPath(), layout.ReleaseDir(digest)} {
		if err := layout.checkOwned(path, true); err != nil {
			return err
		}
	}
	path := layout.BinaryPath(digest)
	if err := layout.checkOwned(path, false); err != nil {
		return err
	}
	observed, _, err := hashFile(path)
	if err != nil {
		return err
	}
	if observed != digest {
		return fmt.Errorf("%w: release %s bytes changed", ErrUnsafe, digest)
	}
	return nil

func (layout Layout) flipCurrent(digest string) error { return layout.flipLink(currentLink, digest) }

func (layout Layout) flipLink(name, digest string) error {
	temporary := filepath.Join(layout.Root, "."+name+"-"+digest[:16])
	_ = os.Remove(temporary)
	if err := os.Symlink(releasesDir+"/"+digest, temporary); err != nil {
		return err
	}
	if err := os.Rename(temporary, filepath.Join(layout.Root, name)); err != nil {
		_ = os.Remove(temporary)
		return err
	}
	return syncDir(layout.Root)
}

func hashFile(path string) (string, int64, error) {
	file, err := os.Open(path)
	if err != nil {
		return "", 0, err
	}
	defer file.Close()
	hash := sha256.New()
	size, err := io.Copy(hash, io.LimitReader(file, MaxBinaryBytes+1))
	if err != nil {
		return "", 0, err
	}
	if size > MaxBinaryBytes {
		return "", 0, fmt.Errorf("%w: binary exceeds %d bytes", ErrInvalid, MaxBinaryBytes)
	}
	return hex.EncodeToString(hash.Sum(nil)), size, nil
}

func syncDir(path string) error {
	directory, err := os.Open(path)
	if err != nil {
		return err
	}
	defer directory.Close()
	return directory.Sync()
}

// writeFileAtomic replaces path with data through a synced temporary file.
func writeFileAtomic(path string, data []byte, mode os.FileMode) error {
	directory := filepath.Dir(path)
	file, err := os.CreateTemp(directory, "."+filepath.Base(path)+"-*")
	if err != nil {
		return err
	}
	name := file.Name()
	defer os.Remove(name)
	if _, err := file.Write(data); err != nil {
		file.Close()
		return err
	}
	if err := file.Chmod(mode); err != nil {
		file.Close()
		return err
	}
	if err := file.Sync(); err != nil {
		file.Close()
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	if err := os.Rename(name, path); err != nil {
		return err
	}
	return syncDir(directory)
}

// readBounded reads a small regular state file without following a final
// symlink. The open is nonblocking and the opened descriptor must be a
// regular file: a FIFO planted in a controller-writable directory would
// otherwise block the open, and with it every locked update command.
func readBounded(path string, maximum int64) ([]byte, error) {
	fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW|syscall.O_NONBLOCK, 0)
	if err != nil {
		return nil, &os.PathError{Op: "open", Path: path, Err: err}
	}
	file := os.NewFile(uintptr(fd), path)
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return nil, err
	}
	if !info.Mode().IsRegular() {
		return nil, fmt.Errorf("%w: %s is not a regular file", ErrInvalid, path)
	}
	data, err := io.ReadAll(io.LimitReader(file, maximum+1))
	if err != nil {
		return nil, err
	}
	if int64(len(data)) > maximum {
		return nil, fmt.Errorf("%w: %s is too large", ErrInvalid, path)
	}
	return data, nil

func (layout Layout) Lock() (func(), error) {
	if err := layout.ensureDirs(); err != nil {
		return nil, err
	}
	path := filepath.Join(layout.Root, lockFile)
	fd, err := syscall.Open(path, syscall.O_RDWR|syscall.O_CREAT|syscall.O_CLOEXEC|syscall.O_NOFOLLOW, 0o600)
	if err != nil {
		return nil, &os.PathError{Op: "open", Path: path, Err: err}
	}
	file := os.NewFile(uintptr(fd), path)
	if err := layout.checkOwned(path, false); err != nil {
		file.Close()
		return nil, err
	}
	for {
		err = syscall.Flock(fd, syscall.LOCK_EX)
		if !errors.Is(err, syscall.EINTR) {
			break
		}
	}
	if err != nil {
		file.Close()
		return nil, &os.PathError{Op: "flock", Path: path, Err: err}
	}
	return func() { file.Close() }, nil
}

func Seed(layout Layout, bakedBinary string) (string, error) {
	if err := layout.ensureDirs(); err != nil {
		return "", err
	}
	current, err := layout.Current()
	if err != nil || current != "" {
		return current, err
	}
	file, err := os.Open(bakedBinary)
	if err != nil {
		return "", err
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil || !info.Mode().IsRegular() || info.Size() <= 0 || info.Size() > MaxBinaryBytes {
		return "", fmt.Errorf("%w: baked binary", ErrInvalid)
	}
	digest, _, err := hashFile(bakedBinary)
	if err != nil {
		return "", err
	}
	if _, err := os.Lstat(layout.ReleaseDir(digest)); errors.Is(err, os.ErrNotExist) {
		if err := layout.install(file, digest, info.Size(), map[string][]byte{bakedMarkerFile: []byte(bakedBinary + "\n")}); err != nil {
			return "", err
		}
	}
	if err := layout.VerifyRelease(digest); err != nil {
		return "", err
	}
	return digest, layout.flipCurrent(digest)
}

// install writes the binary and metadata into a temporary directory and
// renames it into place, so a release directory is never partially present.
func (layout Layout) install(source io.Reader, digest string, size int64, metadata map[string][]byte) error {
	if !digestRE.MatchString(digest) || size <= 0 || size > MaxBinaryBytes {
		return fmt.Errorf("%w: release identity", ErrInvalid)
	}
	temporary, err := os.MkdirTemp(layout.releasesPath(), ".staging-")
	if err != nil {
		return err
	}
	defer os.RemoveAll(temporary)
	if err := os.Chmod(temporary, 0o755); err != nil {
		return err
	}
	binary, err := os.OpenFile(filepath.Join(temporary, BinaryName), os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o500)
	if err != nil {
		return err
	}
	hash := sha256.New()
	written, copyErr := io.Copy(io.MultiWriter(binary, hash), io.LimitReader(source, size+1))
	if copyErr == nil {
		copyErr = binary.Chmod(0o555)
	}
	if copyErr == nil {
		copyErr = binary.Sync()
	}
	if closeErr := binary.Close(); copyErr == nil {
		copyErr = closeErr
	}
	if copyErr != nil {
		return copyErr
	}
	if written != size || hex.EncodeToString(hash.Sum(nil)) != digest {
		return fmt.Errorf("%w: staged binary differs from its signed size or digest", ErrInvalid)
	}
	for name, data := range metadata {
		if err := writeSyncedFile(filepath.Join(temporary, name), data, 0o444); err != nil {
			return err
		}
	}
	if err := syncDir(temporary); err != nil {
		return err
	}
	if err := os.Rename(temporary, layout.ReleaseDir(digest)); err != nil {
		return err
	}
	if err := syncDir(layout.releasesPath()); err != nil {
		return err
	}
	return layout.VerifyRelease(digest)
}

// writeSyncedFile creates path with data and syncs it before the caller
// syncs and renames the directory, so a crash never keeps a release whose
// metadata files are empty or truncated.
func writeSyncedFile(path string, data []byte, mode os.FileMode) error {
	file, err := os.OpenFile(path, os.O_CREATE|os.O_EXCL|os.O_WRONLY, mode)
	if err != nil {
		return err
	}
	_, err = file.Write(data)
	if err == nil {
		err = file.Chmod(mode)
	}
	if err == nil {
		err = file.Sync()
	}
	if closeErr := file.Close(); err == nil {
		err = closeErr
	}
	return err
}

func (activation Activation) validate() error {
	if activation.Schema != ActivationSchema || !digestRE.MatchString(activation.Target) ||
		!digestRE.MatchString(activation.Previous) || activation.Target == activation.Previous ||
		!entityid.Valid(activation.ActivationID) || !unitRE.MatchString(activation.Unit) ||
		activation.ActivatedAt.IsZero() || !activation.Deadline.After(activation.ActivatedAt) ||
		activation.Deadline.Sub(activation.ActivatedAt) > MaxProofWindow {
		return fmt.Errorf("%w: activation record", ErrInvalid)
	}
	return nil
}

// Pending returns the pending activation, if any.
func (layout Layout) Pending() (Activation, bool, error) {
	data, exists, err := layout.pendingRecord()
	if err != nil || !exists {
		return Activation{}, false, err
	}
	activation, err := decodeActivation(data)
	if err != nil {
		return Activation{}, false, err
	}
	return activation, true, nil
}

func (layout Layout) pendingRecord() ([]byte, bool, error) {
	if err := layout.checkOwned(layout.activationPath(), false); errors.Is(err, os.ErrNotExist) {
		return nil, false, nil
	} else if err != nil {
		return nil, false, err
	}
	data, err := readBounded(layout.activationPath(), maxStateBytes)
	if err != nil {
		return nil, false, err
	}
	return data, true, nil
}

func decodeActivation(data []byte) (Activation, error) {
	var activation Activation
	if err := protocol.DecodeStrict(data, &activation, maxStateBytes); err != nil {
		return Activation{}, fmt.Errorf("%w: activation record: %w", ErrUnreadableActivation, err)
	}
	if err := activation.validate(); err != nil {
		return Activation{}, fmt.Errorf("%w: %w", ErrUnreadableActivation, err)
	}
	return activation, nil
}

func Activate(layout Layout, digest, unit string, now time.Time, window time.Duration) (Activation, error) {
	if window < MinProofWindow || window > MaxProofWindow || !unitRE.MatchString(unit) || now.IsZero() {
		return Activation{}, fmt.Errorf("%w: activation unit or proof window", ErrInvalid)
	}
	// An interrupted rollout restore is finished before the selection
	// changes again, so its recovery can never overwrite this activation.
	if err := layout.finishRestores(); err != nil {
		return Activation{}, err
	}
	if pending, exists, err := layout.Pending(); err != nil {
		return Activation{}, err
	} else if exists {
		if pending.Target == digest && pending.Unit == unit {
			// A retry passes the same gates as a fresh activation: a crash
			// after a rollback marked the target known bad must not
			// re-activate it, and unverified bytes never become current.
			if !now.Before(pending.Deadline) {
				return Activation{}, fmt.Errorf("%w: activation %s passed its deadline; the watchdog resolves it", ErrInvalid, pending.ActivationID)
			}
			if knownBad, err := layout.KnownBad(); err != nil {
				return Activation{}, err
			} else if knownBad[digest] {
				return Activation{}, ErrKnownBad
			}
			if err := layout.VerifyRelease(digest); err != nil {
				return Activation{}, err
			}
			return pending, layout.flipCurrent(digest)
		}
		return Activation{}, fmt.Errorf("%w: activation %s is still pending", ErrInvalid, pending.ActivationID)
	}
	if knownBad, err := layout.KnownBad(); err != nil {
		return Activation{}, err
	} else if knownBad[digest] {
		return Activation{}, ErrKnownBad
	}
	previous, err := layout.Current()
	if err != nil {
		return Activation{}, err
	}
	if previous == "" {
		return Activation{}, fmt.Errorf("%w: seed the baked release before activating another", ErrInvalid)
	}
	if previous == digest {
		return Activation{}, fmt.Errorf("%w: release is already current", ErrInvalid)
	}
	for _, release := range []string{previous, digest} {
		if err := layout.VerifyRelease(release); err != nil {
			return Activation{}, err
		}
	}

	activation := Activation{
		Schema: ActivationSchema, ActivationID: entityid.NewAt(now), Unit: unit,
		Target: digest, Previous: previous, ActivatedAt: now.UTC(), Deadline: now.UTC().Add(window),
	}
	encoded, err := protocol.EncodeJSON(activation)
	if err != nil {
		return Activation{}, err
	}
	if err := writeFileAtomic(layout.activationPath(), encoded, 0o644); err != nil {
		return Activation{}, err
	}
	if err := layout.flipCurrent(digest); err != nil {
		return activation, err
	}
	recordActivation(activation)
	return activation, nil
}

func (layout Layout) KnownBad() (map[string]bool, error) {
	data, err := readBounded(layout.knownBadPath(), maxStateBytes)
	if errors.Is(err, os.ErrNotExist) {
		return map[string]bool{}, nil
	}
	if err != nil {
		return nil, err
	}
	var state knownBadState
	if err := protocol.DecodeStrict(data, &state, maxStateBytes); err != nil {
		return nil, err
	}
	known := make(map[string]bool, len(state.Digests))
	for _, digest := range state.Digests {
		if !digestRE.MatchString(digest) {
			return nil, fmt.Errorf("%w: known-bad digest", ErrInvalid)
		}
		known[digest] = true
	}
	return known, nil
}

func (layout Layout) markKnownBad(digest string) error {
	data, err := readBounded(layout.knownBadPath(), maxStateBytes)
	var state knownBadState
	switch {
	case errors.Is(err, os.ErrNotExist):
	case err != nil:
		return err
	default:
		if err := protocol.DecodeStrict(data, &state, maxStateBytes); err != nil {
			return err
		}
	}
	if slices.Contains(state.Digests, digest) {
		return nil
	}
	state.Digests = append(state.Digests, digest)
	if len(state.Digests) > maxKnownBad {
		state.Digests = state.Digests[len(state.Digests)-maxKnownBad:]
	}
	encoded, err := protocol.EncodeJSON(state)
	if err != nil {
		return err
	}
	return writeFileAtomic(layout.knownBadPath(), encoded, 0o644)
}

func Watch(layout Layout, unit string, proof ProofCheck, now time.Time) (Outcome, Activation, error) {
	// A rollout restore interrupted before its link moved is finished
	// first, so neither the watchdog's restart nor the unit's start ever
	// runs the release the restore rejected.
	if err := layout.finishRestores(); err != nil {
		return OutcomeIdle, Activation{}, fmt.Errorf("finish interrupted restore: %w", err)
	}
	activation, pending, err := layout.Pending()
	if errors.Is(err, ErrUnreadableActivation) {
		return layout.resolveUnreadable(err)
	}
	if err != nil || !pending {
		return OutcomeIdle, Activation{}, err
	}
	if activation.Unit != unit {
		// Another unit's watchdog resolves this activation. Once it is long
		// past its deadline no functioning watchdog is left to do so (a
		// mistyped unit, or a unit without the drop-ins): roll it back so it
		// cannot block every later activation on this node.
		if now.Before(activation.Deadline.Add(OrphanedActivationGrace)) {
			return OutcomePending, activation, nil
		}
		slog.Warn("self-update activation of an unwatched unit expired; rolling back",
			"activation", activation.ActivationID, "unit", activation.Unit)
		if err := layout.rollback(activation); err != nil {
			return OutcomeRolledBack, activation, err
		}
		recordResolution(activation, OutcomeRolledBack)
		return OutcomeRolledBack, activation, nil
	}
	// rollback marks the target known bad before it moves the link and
	// removes the record. A known-bad target therefore means a rollback was
	// committed and interrupted: finish it instead of accepting a proof.
	knownBad, err := layout.KnownBad()
	if err != nil {
		return OutcomePending, activation, err
	}
	if knownBad[activation.Target] {
		slog.Warn("self-update rollback was interrupted; finishing it", "activation", activation.ActivationID)
		if err := layout.rollback(activation); err != nil {
			return OutcomeRolledBack, activation, err
		}
		recordResolution(activation, OutcomeRolledBack)
		return OutcomeRolledBack, activation, nil
	}
	// Only a target that is actually selected can be confirmed. Otherwise
	// the activation stays pending until its deadline rolls it back.
	current, err := layout.Current()
	if err != nil {
		return OutcomePending, activation, err
	}
	targetErr := layout.VerifyRelease(activation.Target)
	if targetErr == nil && current == activation.Target && len(proof.PublicKey) == ed25519.PublicKeySize {
		if wire, err := readProof(proof.File); err == nil {
			if verified, err := VerifyVersionProof(wire, proof.PublicKey, activation, now); err == nil && !processRunning(verified.ProcessID) {
				// A proof only confirms while the process that signed it
				// still runs: one that crashed right after proving must not
				// confirm the activation at the next check.
				slog.Warn("self-update version proof process is gone", "activation", activation.ActivationID, "pid", verified.ProcessID)
			} else if err == nil {
				if err := layout.rememberConfirmed(activation.Target); err != nil {
					return OutcomePending, activation, err
				}
				// The confirmed release runs the image's root steps from
				// now on (Delegate).
				if err := layout.flipLink(knownGoodLink, activation.Target); err != nil {
					return OutcomePending, activation, err
				}
				if err := os.Remove(layout.activationPath()); err != nil {
					return OutcomePending, activation, err
				}
				if err := syncDir(layout.Root); err != nil {
					return OutcomeConfirmed, activation, err
				}
				recordResolution(activation, OutcomeConfirmed)
				return OutcomeConfirmed, activation, nil
			} else {
				slog.Warn("self-update version proof rejected", "activation", activation.ActivationID, "error", err)
			}
		} else if !errors.Is(err, os.ErrNotExist) {
			slog.Warn("self-update version proof unreadable", "activation", activation.ActivationID, "error", err)
		}
	}
	if targetErr == nil && now.Before(activation.Deadline) {
		return OutcomePending, activation, nil
	}
	if err := layout.rollback(activation); err != nil {
		return OutcomeRolledBack, activation, err
	}
	recordResolution(activation, OutcomeRolledBack)
	return OutcomeRolledBack, activation, nil
}

// Backstop rolls back a damaged target or a readable activation still pending
// OrphanedActivationGrace past its deadline. The image-baked binary runs it
// after the known-good release ran prepare or the watchdog, so a release
// whose steps succeed without enforcing deadlines cannot keep an unproven
// target current. A record it cannot read belongs to the newer release that
// wrote it and is left alone. The caller holds Lock.
func Backstop(layout Layout, now time.Time) (Outcome, Activation, error) {
	activation, pending, err := layout.Pending()
	if errors.Is(err, ErrUnreadableActivation) {
		return OutcomeIdle, Activation{}, nil
	}
	if err != nil || !pending {
		return OutcomeIdle, Activation{}, err
	}
	bad, err := layout.KnownBad()
	if err != nil {
		return OutcomePending, activation, err
	}
	if !bad[activation.Target] && layout.VerifyRelease(activation.Target) == nil && now.Before(activation.Deadline.Add(OrphanedActivationGrace)) {
		return OutcomePending, activation, nil
	}
	slog.Warn("self-update activation is damaged or outlived its deadline; rolling back",
		"activation", activation.ActivationID, "unit", activation.Unit)
	if err := layout.rollback(activation); err != nil {
		return OutcomeRolledBack, activation, err
	}
	recordResolution(activation, OutcomeRolledBack)
	return OutcomeRolledBack, activation, nil
}

// processRunning reports whether pid names a live process. Tests replace it.
var processRunning = func(pid int64) bool {
	if pid <= 0 || pid > math.MaxInt32 {
		return false
	}
	err := syscall.Kill(int(pid), 0)
	return err == nil || errors.Is(err, syscall.EPERM)
}

func (layout Layout) rollback(activation Activation) error {
	if err := layout.markKnownBad(activation.Target); err != nil {
		return err
	}
	if err := layout.VerifyRelease(activation.Previous); err != nil {
		return fmt.Errorf("previous release cannot be restored: %w", err)
	}
	if err := layout.flipCurrent(activation.Previous); err != nil {
		return err
	}
	// The rejected process may still run: keep a restart obligation that
	// outlives this invocation before the activation record goes away.
	if err := layout.markRestartPending(activation.Unit); err != nil {
		return err
	}
	if err := os.Remove(layout.activationPath()); err != nil {
		return err
	}
	return syncDir(layout.Root)
}

// Prepare runs as root before every unit start (ExecStartPre=+). It seeds
// the baked release on first use, resolves an expired activation, and
// refuses to start a current release whose bytes no longer verify.
func Prepare(layout Layout, unit, bakedBinary string, proof ProofCheck, now time.Time) (Outcome, error) {
	if _, err := Seed(layout, bakedBinary); err != nil {
		return OutcomeIdle, fmt.Errorf("seed baked release: %w", err)
	}
	// Prepare runs while the unit (re)starts, so the process behind any
	// existing proof is gone: a proof never confirms across a restart. The
	// new process proves itself again for the watchdog; prepare only
	// resolves expired, unwatched or unreadable activations; its proof
	// argument is accepted for the drop-in's flags and not used to confirm.
	outcome, activation, err := Watch(layout, unit, ProofCheck{}, now)
	if err != nil {
		return outcome, err
	}
	// The unit is starting now, so any restart a rollback still owed it is
	// being served by this start.
	if unitRE.MatchString(unit) {
		if err := layout.ClearRestartPending(unit); err != nil {
			return outcome, err
		}
	}
	current, err := layout.Current()
	if err != nil {
		return outcome, err
	}
	// The units on a node share the current link. A unit never starts the
	// unconfirmed target of another unit's activation: it cannot prove it,
	// and that activation's rollback does not restart it. Its restart policy
	// retries once the activation is resolved.
	if outcome == OutcomePending && activation.Unit != unit && current == activation.Target {
		return outcome, fmt.Errorf("%w: %s waits for the pending activation of %s", ErrInvalid, unit, activation.Unit)
	}
	if err := layout.VerifyRelease(current); err != nil {
		return outcome, fmt.Errorf("current release does not verify: %w", err)
	}
	if removed, err := layout.PruneReleases(now); err != nil {
		slog.Warn("self-update release pruning failed", "error", err)
	} else if len(removed) > 0 {
		slog.Info("self-update pruned settled releases", "releases", removed)
	}
	return outcome, nil
}

func (layout Layout) restartMarkerPath(unit string) string {
	return filepath.Join(layout.Root, restartMarkerPrefix+unit)
}

// markRestartPending records that unit must restart onto the restored
// release. It is written before the activation record is removed, so no
// interruption can lose both.
func (layout Layout) markRestartPending(unit string) error {
	if !unitRE.MatchString(unit) {
		return fmt.Errorf("%w: unit", ErrInvalid)
	}
	return writeFileAtomic(layout.restartMarkerPath(unit), []byte(unit+"\n"), 0o644)
}

// RestartPending reports whether a rollback of unit has not been followed by
// a restart yet. The caller holds Lock.
func (layout Layout) RestartPending(unit string) (bool, error) {
	if !unitRE.MatchString(unit) {
		return false, fmt.Errorf("%w: unit", ErrInvalid)
	}
	err := layout.checkOwned(layout.restartMarkerPath(unit), false)
	if errors.Is(err, os.ErrNotExist) {
		return false, nil
	}
	return err == nil, err
}

// ClearRestartPending removes the marker once unit restarted. Prepare calls
// it at every unit start; the watchdog after a successful restart. The caller
// holds Lock.
func (layout Layout) ClearRestartPending(unit string) error {
	if !unitRE.MatchString(unit) {
		return fmt.Errorf("%w: unit", ErrInvalid)
	}
	if err := os.Remove(layout.restartMarkerPath(unit)); err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	return nil
}

func proofScope(activationID, digest string) trust.Scope {
	return trust.Scope{
		Domain: ProofDomain, DeploymentID: activationID, Cell: "local",
		Environment: "node", Role: "version-proof", Slot: digest,
	}
}

// SignVersionProof signs proof with the process's own identity key.
func SignVersionProof(proof VersionProof, privateKey ed25519.PrivateKey, now time.Time) ([]byte, error) {
	if proof.Schema != ProofSchema || !entityid.Valid(proof.ActivationID) || !unitRE.MatchString(proof.Unit) ||
		!digestRE.MatchString(proof.BinarySHA256) || proof.ProcessID <= 0 || proof.ObservedAt.IsZero() {
		return nil, fmt.Errorf("%w: version proof", ErrInvalid)
	}
	payload, err := trust.EncodePayload(proof)
	if err != nil {
		return nil, err
	}
	envelope, err := trust.Sign(payload, proofScope(proof.ActivationID, proof.BinarySHA256), now, now.Add(ProofLifetime), privateKey)
	if err != nil {
		return nil, err
	}
	return trust.EncodeEnvelope(envelope)
}

// VerifyVersionProof accepts only a currently valid proof, signed by
// publicKey, for exactly this activation, unit and target digest, issued
// after the activation moved the current link.
func VerifyVersionProof(wire []byte, publicKey ed25519.PublicKey, activation Activation, now time.Time) (VersionProof, error) {
	if err := activation.validate(); err != nil {
		return VersionProof{}, err
	}
	keys, err := trust.ParseKeyring(publicKey)
	if err != nil {
		return VersionProof{}, err
	}
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return VersionProof{}, err
	}
	payload, err := trust.VerifyCurrent(envelope, proofScope(activation.ActivationID, activation.Target), keys, now,
		trust.Policy{MaxLifetime: ProofLifetime, ClockSkew: proofClock})
	if err != nil {
		return VersionProof{}, err
	}
	var proof VersionProof
	if err := protocol.DecodeStrict(payload, &proof, maxStateBytes); err != nil {
		return VersionProof{}, err
	}
	if proof.Schema != ProofSchema || proof.ActivationID != activation.ActivationID || proof.Unit != activation.Unit ||
		proof.BinarySHA256 != activation.Target || proof.ProcessID <= 0 ||
		envelope.IssuedAt.Before(activation.ActivatedAt.Truncate(time.Second)) || proof.ObservedAt.Before(activation.ActivatedAt) {
		return VersionProof{}, fmt.Errorf("%w: version proof is not fresh for this activation", ErrInvalid)
	}
	// A process that became ready only after its proof window must not be
	// confirmed by a late check. A check after the deadline still accepts a
	// proof produced in time.
	if envelope.IssuedAt.After(activation.Deadline) || proof.ObservedAt.After(activation.Deadline) {
		return VersionProof{}, fmt.Errorf("%w: version proof was produced after the activation deadline", ErrInvalid)
	}
	return proof, nil
}

// DefaultProofFile is the proof file of a unit whose config names none: its
// systemd StateDirectory beside the release root, which the unit can write
// and the root-run watchdog can read. For DefaultRoot that is
// /var/lib/<unit name>/selfupdate-proof.json. The release root itself stays
// writable only by root.
func DefaultProofFile(root, unit string) string {
	return filepath.Join(filepath.Dir(root), strings.TrimSuffix(unit, ".service"), "selfupdate-proof.json")
}

func readProof(path string) ([]byte, error) {
	if path == "" {
		return nil, os.ErrNotExist
	}
	wire, err := readBounded(path, trust.MaxEnvelopeBytes)
	if err != nil {
		return nil, err
	}
	if len(wire) == 0 {
		return nil, errors.New("empty version proof")
	}
	return wire, nil
}

func captureLog(t *testing.T) *bytes.Buffer {
	t.Helper()
	t.Setenv("JOURNAL_STREAM", "")
	var output bytes.Buffer
	logger, err := observability.NewLogger(&output, observability.LogConfig{}, nil)
	if err != nil {
		t.Fatal(err)
	}
	previous := slog.Default()
	observability.ConfigureDefault(logger)
	t.Cleanup(func() { slog.SetDefault(previous) })
	return &output
}

func (c command) delegate(layout selfupdate.Layout, args []string) bool {
	if os.Getenv(delegatedEnv) != "" {
		return false
	}
	digest, err := layout.Delegate()
	if err != nil {
		slog.Warn("self-update known-good release is unusable; the image-baked binary runs the step", "error", err)
	}
	if err != nil || digest == "" {
		return false
	}
	unit := ""
	for index, arg := range args {
		if arg == "--unit" && index+1 < len(args) {
			unit = args[index+1]
		}
		if value, ok := strings.CutPrefix(arg, "--unit="); ok {
			unit = value
		}
	}
	if unit == selfupdate.ControllerUnit {
		accepted, inputs, err := controllerTrust(unit)
		if err != nil {
			return false
		}
		if accepted != nil && c.checkControllerRelease(layout, digest, *accepted, inputs) != nil {
			return false
		}
	}
	ctx, cancel := context.WithTimeout(c.ctx, delegateTimeout)
	defer cancel()
	step := exec.CommandContext(ctx, layout.BinaryPath(digest), append([]string{"selfupdate"}, args...)...)
	step.Env = append(os.Environ(), delegatedEnv+"=1")
	step.Stdout, step.Stderr = c.output, os.Stderr
	step.WaitDelay = time.Second
	if err := step.Run(); err != nil {
		slog.WarnContext(ctx, "self-update known-good release failed the step; the image-baked binary runs it", "release", digest, "error", err)
		return false
	}
	return true
}

func (c command) backstopPrepare(layout selfupdate.Layout, unit string) error {
	unlock, err := layout.Lock()
	if err != nil {
		return err
	}
	defer unlock()
	accepted, inputs, err := controllerTrust(unit)
	if err != nil {
		return err
	}
	recovered := false
	if accepted != nil {
		if _, err := c.checkControllerRecovery(layout, *accepted, inputs, true, ""); err != nil {
			return err
		}
		if err := c.requireControllerCompletion(layout, *accepted, inputs); err != nil {
			return err
		}
		recovered, err = c.recoverControllerActivation(layout, *accepted, inputs)
		if err != nil {
			return err
		}
	}
	outcome, activation, err := selfupdate.Backstop(layout, c.now())
	if err != nil {
		return err
	}
	// This start serves the restart the rollback owes the unit.
	if recovered || outcome == selfupdate.OutcomeRolledBack && activation.Unit == unit {
		if err := layout.ClearRestartPending(unit); err != nil {
			return err
		}
	}
	current, err := layout.Current()
	if err != nil {
		return err
	}
	if err := layout.VerifyRelease(current); err != nil {
		return fmt.Errorf("current release does not verify: %w", err)
	}
	return nil
}

func controllerTrust(unit string) (*bootstrapstart.AcceptedIdentity, bootstrapstart.TrustInputs, error) {
	if unit != selfupdate.ControllerUnit {
		return nil, bootstrapstart.TrustInputs{}, nil
	}
	accepted, err := acceptedIdentity()
	if errors.Is(err, os.ErrNotExist) {
		present, journalErr := acceptedJournalPresent()
		if journalErr != nil {
			return nil, bootstrapstart.TrustInputs{}, journalErr
		}
		if present {
			return nil, bootstrapstart.TrustInputs{}, errors.New("identity rekey journal exists without accepted controller identity")
		}
		return nil, bootstrapstart.TrustInputs{}, nil
	}
	if err != nil {
		return nil, bootstrapstart.TrustInputs{}, err
	}
	if err := accepted.Validate(); err != nil {
		return nil, bootstrapstart.TrustInputs{}, err
	}
	if err := acceptedPrestart(accepted); err != nil {
		return nil, bootstrapstart.TrustInputs{}, err
	}
	inputs, err := acceptedTrustInputs(accepted)
	return new(accepted), inputs, err
}

func (c command) requireControllerCompletion(layout selfupdate.Layout, accepted bootstrapstart.AcceptedIdentity, inputs bootstrapstart.TrustInputs) error {
	present, err := acceptedJournalPresent()
	if err != nil || !present {
		return err
	}
	current, err := layout.Current()
	if err != nil || current == "" {
		return errors.New("identity rekey completion requires a trusted current binary")
	}
	rollback, err := c.controllerRollback(layout, accepted, inputs)
	if err != nil {
		return err
	}
	if current == rollback.Target {
		current = rollback.Previous
	}
	if err := c.checkControllerRelease(layout, current, accepted, inputs); err != nil {
		return err
	}
	return completionProbe(c.ctx, layout.BinaryPath(current))
}

// The step spools of the controller and the host, and the image's trust
// roots; tests replace them.
var (
	rolloutSpoolDir        = rolloutexec.DefaultSpoolDir
	hostSpoolDir           = rolloutexec.HostSpoolDir
	bakedInputs            = bootstrapstart.LoadBakedInputs
	acceptedIdentity       = func() (bootstrapstart.AcceptedIdentity, error) { return bootstrapstart.NewMarkerStore().ReadIdentity() }
	acceptedTrustInputs    = bootstrapstart.LoadTrustInputs
	acceptedPrestart       = bootstrapstart.CheckIdentityRekeyPrestart
	acceptedJournalPresent = bootstrapstart.IdentityRekeyJournalPresent
	completionProbe        = runIdentityRekeyCompletionProbe
	checkAcceptedBinary    = checkAcceptedBinaryContract
	// installGeneration is prepare's material step for the controller unit.
	installGeneration = bootstrapstart.InstallGeneration
)

func (c command) checkControllerRelease(layout selfupdate.Layout, digest string, accepted bootstrapstart.AcceptedIdentity, inputs bootstrapstart.TrustInputs) error {
	bad, err := layout.KnownBad()
	if err != nil {
		return err
	}
	if bad[digest] {
		return selfupdate.ErrKnownBad
	}
	if err := layout.VerifyRelease(digest); err != nil {
		return err
	}
	if digest == accepted.Binary.SHA256 {
		info, err := os.Stat(layout.BinaryPath(digest))
		if err != nil || info.Size() != accepted.Binary.Size {
			return selfupdate.ErrInvalid
		}
	} else {
		receipt, delegation, err := layout.ReleaseReceipt(digest)
		if err != nil {
			return err
		}
		envelope, err := trust.DecodeEnvelope(receipt)
		if err != nil {
			return err
		}
		var verified release.HistoricalBinary
		switch envelope.Scope.Domain {
		case release.BinaryDomain:
			verified, err = release.VerifyBinaryHistorical(receipt, delegation, inputs.Roots.Historical, release.BinaryExpectation{Environment: accepted.Environment})
		case release.UpdateReceiptDomain:
			verified, err = release.VerifyBinaryUpdateHistorical(receipt, delegation, inputs.Roots.Historical,
				release.UpdateExpectation{Environment: accepted.Environment, Cell: accepted.Cell, Architecture: accepted.Binary.Architecture})
		default:
			return errors.New("controller release has an unsupported receipt domain")
		}
		if err != nil {
			return err
		}
		if !verified.IsVerified() || verified.Receipt().SHA256 != digest || verified.Receipt().GOARCH != accepted.Binary.Architecture {
			return selfupdate.ErrInvalid
		}
	}
	return checkAcceptedBinary(c.ctx, layout.BinaryPath(digest), accepted)
}

// checkControllerTransitions checks every release this root step could select;
// a valid successor need not equal the accepted executable baseline.
func (c command) checkControllerTransitions(layout selfupdate.Layout, accepted bootstrapstart.AcceptedIdentity, inputs bootstrapstart.TrustInputs, starting bool, baked string) error {
	return c.checkControllerSelections(layout, accepted, inputs, starting, baked, "")
}

func (c command) checkControllerRecovery(layout selfupdate.Layout, accepted bootstrapstart.AcceptedIdentity, inputs bootstrapstart.TrustInputs, starting bool, baked string) (bool, error) {
	rollback, err := c.controllerRollback(layout, accepted, inputs)
	if err != nil {
		return false, err
	}
	return rollback.Target != "", c.checkControllerSelections(layout, accepted, inputs, starting, baked, rollback.Target)

func (c command) controllerRollback(layout selfupdate.Layout, accepted bootstrapstart.AcceptedIdentity, inputs bootstrapstart.TrustInputs) (selfupdate.Activation, error) {
	activation, pending, err := layout.Pending()
	if errors.Is(err, selfupdate.ErrUnreadableActivation) {
		activation, err = layout.RecoveryActivation()
		if err != nil {
			return selfupdate.Activation{}, err
		}
		if activation.Unit == selfupdate.ControllerUnit {
			return activation, nil
		}
		return selfupdate.Activation{}, nil
	}
	if err != nil {
		return selfupdate.Activation{}, err
	}
	if pending && activation.Unit == selfupdate.ControllerUnit && c.checkControllerRelease(layout, activation.Target, accepted, inputs) != nil {
		return activation, c.ctx.Err()
	}
	intents, err := layout.PendingRestores()
	if err != nil {
		return selfupdate.Activation{}, err
	}
	for _, intent := range intents {
		if intent.Unit == selfupdate.ControllerUnit {
			return selfupdate.Activation{Target: intent.Rejected, Previous: intent.Target, Unit: intent.Unit}, nil
		}
	}
	return selfupdate.Activation{}, nil
}

func (c command) checkControllerSelections(layout selfupdate.Layout, accepted bootstrapstart.AcceptedIdentity, inputs bootstrapstart.TrustInputs, starting bool, baked, unverified string) error {
	activation, pending, err := layout.Pending()
	if errors.Is(err, selfupdate.ErrUnreadableActivation) && unverified != "" {
		activation, err = layout.RecoveryActivation()
		pending = err == nil && activation.Unit == selfupdate.ControllerUnit && activation.Target == unverified
		if err == nil && !pending {
			return selfupdate.ErrInvalid
		}
	}
	if err != nil {
		return err
	}
	if pending {
		if err := c.checkControllerRelease(layout, activation.Previous, accepted, inputs); err != nil {
			return fmt.Errorf("controller rollback predecessor: %w", err)
		}
		if activation.Target != unverified {
			if err := c.checkControllerRelease(layout, activation.Target, accepted, inputs); err != nil {
				return err
			}
		}
	}
	{
		current, err := layout.Current()
		if err != nil {
			return err
		}
		if current != "" && current != unverified {
			if err := c.checkControllerRelease(layout, current, accepted, inputs); err != nil {
				return err
			}
		} else if current == "" {
			if !starting || baked == "" {
				return errors.New("accepted controller has no current release")
			}
			if err := checkAcceptedBinary(c.ctx, baked, accepted); err != nil {
				return err
			}
		}
	}
	delegate, err := layout.Delegate()
	if err != nil {
		return err
	}
	if delegate != "" {
		if err := c.checkControllerRelease(layout, delegate, accepted, inputs); err != nil {
			return err
		}
	}
	intents, err := layout.PendingRestores()
	if err != nil {
		return err
	}
	for _, intent := range intents {
		if err := c.checkControllerRelease(layout, intent.Target, accepted, inputs); err != nil {
			return fmt.Errorf("controller restore target: %w", err)
		}
	}
	return nil
}

func (c command) rolloutStep(layout selfupdate.Layout, unit, configPath string) {
	role, err := readRolloutRole(configPath)
	if err != nil {
		if !errors.Is(err, os.ErrNotExist) {
			slog.Warn("rollout step agent: role config is unusable", "config", configPath, "error", err)
		}
		return
	}
	node, spool := role.Host.Node, hostSpoolDir
	var public ed25519.PublicKey
	if unit == selfupdate.ControllerUnit {
		node, spool = role.NATS.Instance, rolloutSpoolDir
		public, err = readIdentityPublicKey(role.Controller.ResponseKeyFile)
	} else {
		// A host on a controller's VM shares its release root and moves with
		// the controller; a step for it would move the controller's link.
		if _, err := os.Stat(filepath.Join(filepath.Dir(configPath), "controller.json")); err == nil {
			return
		}
		if role.Host.Node == "" {
			return
		}
		var decoded []byte
		decoded, err = base64.StdEncoding.DecodeString(strings.TrimSpace(role.Host.ControllerPublicKey))
		if err == nil && len(decoded) != ed25519.PublicKeySize {
			err = errors.New("not an Ed25519 public key")
		}
		public = decoded
	}
	if err != nil {
		slog.Warn("rollout step agent: the leaders' key is unusable", "error", err)
		return
	}
	leaders, err := trust.ParseKeyring(public)
	if err != nil {
		slog.Warn("rollout step agent: the leaders' key is unusable", "error", err)
		return
	}
	var receiptRoots trust.Keyring
	var environment, cell string
	var acceptedWire []byte
	if unit == selfupdate.ControllerUnit {
		accepted, inputs, err := controllerTrust(unit)
		if err != nil || accepted == nil {
			slog.Warn("rollout step agent: accepted controller trust is unavailable", "error", err)
			return
		}
		if role.NATS.Cell != strings.ToLower(accepted.Cell) {
			slog.Warn("rollout step agent: configured cell differs from accepted cell")
			return
		}
		if err := c.checkControllerTransitions(layout, *accepted, inputs, true, ""); err != nil {
			slog.Warn("rollout step agent: controller release is incompatible", "error", err)
			return
		}
		acceptedWire, err = bootstrapstart.EncodeAcceptedIdentity(*accepted)
		if err != nil {
			return
		}
		receiptRoots, environment, cell = inputs.Roots.Current, accepted.Environment, accepted.Cell
	} else {
		baked, err := bakedInputs()
		if err != nil {
			slog.Warn("rollout step agent: image trust roots are unusable", "error", err)
			return
		}
		roots, err := trust.VerifyRootChain(baked.Genesis, baked.Identity.ChainIdentity(), baked.Chain)
		if err != nil {
			slog.Warn("rollout step agent: adopted root chain does not verify", "error", err)
			return
		}
		receiptRoots, environment, cell = roots.Current, baked.Identity.Environment, strings.ToUpper(role.NATS.Cell)
	}
	verifier := selfupdate.ReceiptPolicy{Roots: receiptRoots, Environment: environment,
		Cell: cell, Architecture: runtime.GOARCH}
	agent := &rolloutexec.Agent{Cell: role.NATS.Cell, Unit: node, SystemdUnit: unit, Layout: layout, Leaders: leaders,
		Now: c.now, Restart: func(context.Context, string) error { return nil }}
	if unit == selfupdate.ControllerUnit {
		agent.Guard = func(ctx context.Context, step rolloutexec.StepCommand) error {
			accepted, inputs, err := controllerTrust(unit)
			if err != nil {
				return err
			}
			if accepted == nil {
				return errors.New("accepted controller identity is missing")
			}
			fresh, err := bootstrapstart.EncodeAcceptedIdentity(*accepted)
			if err != nil || !bytes.Equal(fresh, acceptedWire) {
				return errors.New("accepted controller identity changed during rollout")
			}
			if err := c.checkControllerTransitions(layout, *accepted, inputs, true, ""); err != nil {
				return err
			}
			if err := c.requireControllerCompletion(layout, *accepted, inputs); err != nil {
				return err
			}
			if _, err := os.Stat(layout.BinaryPath(step.Digest)); errors.Is(err, os.ErrNotExist) {
				return nil
			} else if err != nil {
				return err
			}
			return (command{ctx: ctx}).checkControllerRelease(layout, step.Digest, *accepted, inputs)
		}
	}
	if err := rolloutexec.ApplySpooled(c.ctx, agent, spool, verifier); err != nil {
		slog.Warn("rollout step agent", "error", err)
	}
}

func acceptedDigest(wire []byte) string {
	sum := sha256.Sum256(wire)
	return hex.EncodeToString(sum[:])
}

