func signAcceptedSuccessor(t *testing.T, data []byte, now time.Time, root ed25519.PrivateKey, roots trust.Keyring) ([]byte, []byte) {
	t.Helper()
	public, leaf, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	keyID, err := trust.KeyID(public)
	if err != nil {
		t.Fatal(err)
	}
	encoded, err := trust.EncodeDelegatedPublicKey(public)
	if err != nil {
		t.Fatal(err)
	}
	source := strings.Repeat("e", 40)
	delegation, err := release.SignUpdateDelegation(release.BinaryUpdateDelegation{
		Schema: release.UpdateDelegationSchema, SubjectKeyID: keyID, SubjectPublicKey: encoded,
		Environment: "canary", Architectures: []string{runtime.GOARCH}, Repository: release.QualificationRepository,
		Workflow: release.QualificationWorkflow, Ref: release.LineageRef, LineageBase: source,
	}, now.Add(-time.Minute), now.Add(time.Hour), root)
	if err != nil {
		t.Fatal(err)
	}
	delegationWire, err := trust.EncodeEnvelope(delegation)
	if err != nil {
		t.Fatal(err)
	}
	binary := release.BinaryReceipt{Schema: release.BinarySchema, SourceRevision: source, GoVersion: release.DefaultGoVersion, GOOS: "linux", GOARCH: runtime.GOARCH,
		ELFMachine: map[string]string{"amd64": "Advanced Micro Devices X86-64", "arm64": "AArch64"}[runtime.GOARCH], Static: true,
		Bytes: int64(len(data)), SHA256: acceptedDigest(data), QualificationSHA256: acceptedDigest([]byte("qualification"))}
	qualified := release.ProductionQualification{Schema: release.ProductionQualificationSchema,
		Candidate: release.ProductionExpectation{SourceRevision: source, ArtifactSHA256: binary.SHA256,
			QualificationSHA256: binary.QualificationSHA256, Cell: "GRU", Environment: "canary",
			Runtime: release.ProductionRuntime, Architecture: runtime.GOARCH, Role: "orchestrator"}}
	for _, gate := range []string{"runtime-ha", "workload-safety"} {
		evidence := []byte("test-only " + gate + " evidence")
		qualified.Evidence = append(qualified.Evidence, release.ProductionGateEvidence{Gate: gate,
			SHA256: acceptedDigest(evidence), Bytes: int64(len(evidence)), CompletedAt: now.Add(-time.Second)})
	}
	payload, err := trust.EncodePayload(qualified)
	if err != nil {
		t.Fatal(err)
	}
	proof, err := trust.Sign(payload, release.ProductionQualificationScope(qualified.Candidate), now, now.Add(30*time.Minute), root)
	if err != nil {
		t.Fatal(err)
	}
	proofWire, err := trust.EncodeEnvelope(proof)
	if err != nil {
		t.Fatal(err)
	}
	update := release.BinaryUpdateReceipt{Schema: release.UpdateReceiptSchema, Binary: binary, Cell: "GRU",
		DelegationSHA256: acceptedDigest(delegationWire), Production: &release.ProductionProof{Qualification: proofWire},
		Lineage: release.SourceLineage{Repository: release.QualificationRepository, Workflow: release.QualificationWorkflow,
			Ref: release.LineageRef, LineageBase: source, QualificationRunID: 10, QualificationRunNum: 5}}
	payload, err = trust.EncodePayload(update)
	if err != nil {
		t.Fatal(err)
	}
	receipt, err := trust.Sign(payload, release.UpdateReceiptScope(update, "canary"), now, now.Add(30*time.Minute), leaf)
	if err != nil {
		t.Fatal(err)
	}
	receiptWire, err := trust.EncodeEnvelope(receipt)
	if err != nil {
		t.Fatal(err)
	}
	return receiptWire, delegationWire
}

func (identity AcceptedIdentity) Validate() error {
	if identity.SchemaVersion != 1 || !entityid.Valid(identity.OperationID) || !entityid.Valid(identity.DeploymentID) ||
		identity.Origin != identityrekey.AcceptanceOriginInitial && identity.Origin != identityrekey.AcceptanceOriginRekey ||
		!entityid.Valid(identity.ClusterID) || !release.ValidEnvironment(identity.Environment) || !catalog.IsCell(identity.Cell) ||
		!slices.Equal(identity.ControllerSlots, []string{"controller-a", "controller-b", "controller-c"}) ||
		!slices.Contains(identity.ControllerSlots, identity.Slot) || !slices.Contains(identity.ControllerSlots, identity.SeedSlot) ||
		len(identity.ControllerBindings) == 0 || len(identity.ControllerBindings) > 3 ||
		identity.AcceptedAt.IsZero() || identity.AcceptedAt.Location() != time.UTC ||
		identity.MaterialGenerationSHA256 != "" && !markerDigestRE.MatchString(identity.MaterialGenerationSHA256) ||
		identity.ManagedMaterial != nil && identity.ManagedMaterial.Validate() != nil {
		return ErrAcceptedIdentity
	}
	if err := validateAcceptedBroker(identity.Broker); err != nil {
		return err
	}
	localFound := false
	for i, binding := range identity.ControllerBindings {
		if !slices.Contains(identity.ControllerSlots, binding.Slot) || binding.validate(identity.Cell) != nil ||
			i > 0 && identity.ControllerBindings[i-1].Slot >= binding.Slot {
			return ErrAcceptedIdentity
		}
		if binding.Slot == identity.Slot {
			if binding != identity.localBinding() {
				return ErrAcceptedIdentity
			}
			localFound = true
		}
		for _, prior := range identity.ControllerBindings[:i] {
			if prior.InstanceOCID == binding.InstanceOCID || prior.PrimaryVNICOCID == binding.PrimaryVNICOCID ||
				prior.PrimaryPrivateIP == binding.PrimaryPrivateIP || prior.Store.ServerName == binding.Store.ServerName ||
				prior.Store.RaftNodeID == binding.Store.RaftNodeID {
				return ErrAcceptedIdentity
			}
		}
	}
	if !localFound || len(identity.ConfigSHA256) != 4 || !markerDigestRE.MatchString(identity.ConfigSHA256["controller.json"]) {
		return ErrAcceptedIdentity
	}
	for _, name := range bootstrap.ControllerConfigFileNames {
		if !markerDigestRE.MatchString(identity.ConfigSHA256[name]) {
			return ErrAcceptedIdentity
		}
	}
	if identityrekey.ValidateLaunchMaterialPins(identity.LaunchMaterialSHA256) != nil {
		return ErrAcceptedIdentity
	}
	return validateAcceptedReferences(identity)
}

func validateAcceptedBroker(broker identityrekey.BrokerIdentity) error {
	if !nkeys.IsValidPublicOperatorKey(broker.Operator) {
		return ErrAcceptedIdentity
	}
	accounts := []string{broker.SystemAccount, broker.CellAccount, broker.HostSigner, broker.RoleSigner}
	for _, optional := range []string{broker.AccountSigner, broker.InterRegionAccount} {
		if optional != "" {
			accounts = append(accounts, optional)
		}
	}
	for i, key := range accounts {
		if !nkeys.IsValidPublicAccountKey(key) || slices.Contains(accounts[:i], key) {
			return ErrAcceptedIdentity
		}
	}
	return nil
}

func (binding ControllerBinding) validate(cell string) error {
	address, err := netip.ParseAddr(binding.PrimaryPrivateIP)
	store := binding.Store
	if !acceptedRegionalOCID(binding.InstanceOCID, "instance", cell) || !acceptedRegionalOCID(binding.PrimaryVNICOCID, "vnic", cell) ||
		!release.ValidOCIImageIDForRegion(binding.ImageOCID, cell) || err != nil || !address.Is4() || !address.IsPrivate() ||
		address.String() != binding.PrimaryPrivateIP || !markerDigestRE.MatchString(binding.Binary.SHA256) ||
		binding.Binary.Size <= 0 || binding.Binary.Size > release.MaxArtifactBytes ||
		binding.Binary.Architecture != "amd64" && binding.Binary.Architecture != "arm64" ||
		!filepath.IsAbs(store.Directory) || filepath.Clean(store.Directory) != store.Directory || store.Directory == "/" ||
		len(store.Directory) > 1024 || strings.ContainsAny(store.Directory, "\x00\r\n") ||
		!markerNameRE.MatchString(store.ServerName) || len(store.RaftNodeID) != 8 ||
		!markerDigestRE.MatchString(store.ServerNameSHA256) || !markerDigestRE.MatchString(store.NodeIdentitySHA256) {
		return ErrAcceptedIdentity
	}
	for _, char := range store.RaftNodeID {
		if !(char >= '0' && char <= '9' || char >= 'a' && char <= 'z' || char >= 'A' && char <= 'Z') {
			return ErrAcceptedIdentity
		}
	}
	return nil
}

func acceptedRegionalOCID(value, kind, cell string) bool {
	parts := strings.Split(value, ".")
	if len(value) > 255 || len(parts) != 5 || parts[0] != "ocid1" || parts[1] != kind ||
		parts[2] != "oc1" || parts[3] != catalog.OCIRegion(cell) || parts[4] == "" {
		return false
	}
	for _, char := range parts[4] {
		if !(char >= 'a' && char <= 'z' || char >= '0' && char <= '9' || char == '-') {
			return false
		}
	}
	return true
}

func validateAcceptedReferences(identity AcceptedIdentity) error {
	if len(identity.MaterialReferences) == 0 || len(identity.MaterialReferences) > 64 {
		return ErrAcceptedIdentity
	}
	allowed := bootstrap.MaterialGenerationFiles()
	for _, name := range []string{"route-password", "ticket.pub", "ticket.key", "membership.creds"} {
		allowed[name] = bootstrap.SecretRegionalShared
	}
	for _, name := range []string{"host-nats-issuer.seed", "terrabase-member-ca.pem", "terrabase-member-ca.key"} {
		allowed[name] = bootstrap.SecretHostIssuer
	}
	for _, suffix := range []string{".creds", "-tls-cert.pem", "-tls-key.pem", "-response.key"} {
		allowed[identity.Slot+suffix] = bootstrap.SecretController
	}
	if identity.Slot == identity.SeedSlot {
		allowed["founder-peer.key"] = bootstrap.SecretSeedFounder
		allowed["founder-ledger.key"] = bootstrap.SecretSeedLedgerSigner
	}
	allowed["interregion.jwt"], allowed["interregion-ca.pem"] = bootstrap.SecretInterRegion, bootstrap.SecretInterRegion
	allowed[bootstrap.LinkCredentialsFile] = bootstrap.SecretInterRegion
	cert, key := bootstrap.InterRegionTLSFiles(identity.Slot)
	allowed[cert], allowed[key] = bootstrap.SecretInterRegion, bootstrap.SecretInterRegion
	seen := make(map[string]bool, len(identity.MaterialReferences))
	for _, reference := range identity.MaterialReferences {
		purpose, known := allowed[reference.TargetFile]
		if strings.HasPrefix(reference.TargetFile, "leaf-") && strings.HasSuffix(reference.TargetFile, ".creds") {
			peer := strings.TrimSuffix(strings.TrimPrefix(reference.TargetFile, "leaf-"), ".creds")
			known, purpose = catalog.IsCell(strings.ToUpper(peer)) && peer == strings.ToLower(peer), bootstrap.SecretInterRegion
		}
		wantSlot := ""
		if purpose == bootstrap.SecretController || purpose == bootstrap.SecretSeedFounder || purpose == bootstrap.SecretSeedLedgerSigner ||
			reference.TargetFile == cert || reference.TargetFile == key {
			wantSlot = identity.Slot
		}
		if !known || reference.Purpose != purpose || reference.Slot != wantSlot || reference.ValidateIdentity() != nil ||
			!acceptedRegionalOCID(reference.SecretOCID, "vaultsecret", identity.Cell) || seen[reference.TargetFile] {
			return ErrAcceptedIdentity
		}
		seen[reference.TargetFile] = true
	}
	for _, name := range []string{"operator.jwt", "system.jwt", "cell.jwt", "system.creds", "ca.pem", "route-password",
		"ticket.pub", "ticket.key", "host-nats-issuer.seed", "host-tls-issuer-cert.pem", "host-tls-issuer-key.pem",
		identity.Slot + ".creds", identity.Slot + "-tls-cert.pem", identity.Slot + "-tls-key.pem", identity.Slot + "-response.key"} {
		if !seen[name] {
			return fmt.Errorf("%w: missing material %s", ErrAcceptedIdentity, name)
		}
	}
	if identity.ManagedMaterial != nil && (!seen["terrabase-member-ca.pem"] || !seen["terrabase-member-ca.key"]) {
		return ErrAcceptedIdentity
	}
	issuerCount := 0
	for name, purpose := range allowed {
		if purpose == bootstrap.SecretControllerIssuer && seen[name] {
			issuerCount++
		}
	}
	if issuerCount != 0 && issuerCount != 3 || (identity.Broker.AccountSigner != "") != (issuerCount == 3) {
		return ErrAcceptedIdentity
	}
	if identity.Broker.InterRegionAccount != "" && (!seen["interregion.jwt"] || !seen["interregion-ca.pem"] || !seen[cert] || !seen[key]) {
		return ErrAcceptedIdentity
	}
	return nil
}

func MaterialGenerationFiles() map[string]SecretPurpose {
	return map[string]SecretPurpose{
		"ca.pem": SecretRegionalShared, "operator.jwt": SecretRegionalShared, "system.jwt": SecretRegionalShared,
		"cell.jwt": SecretRegionalShared, "system.creds": SecretRegionalShared,
		"host-tls-issuer-cert.pem": SecretHostIssuer, "host-tls-issuer-key.pem": SecretHostIssuer,
		"controller-tls-issuer-cert.pem": SecretControllerIssuer, "controller-tls-issuer-key.pem": SecretControllerIssuer,
		"controller-account-signer.seed": SecretControllerIssuer,
	}
}

func ValidateLaunchMaterialPins(pins map[string]string) error {
	if len(pins) != 4 {
		return fmt.Errorf("%w: complete public launch input pins are required", ErrCheckpointInvalid)
	}
	for _, name := range []string{"host-enrollment-public.json", "operator-ssh-key.pub",
		"managed-host-image-receipt.json", "managed-host-image-delegation.json"} {
		if !digestRE.MatchString(pins[name]) {
			return fmt.Errorf("%w: public launch input %s", ErrCheckpointInvalid, name)
		}
	}
	return nil
}

func ApplySpooled(ctx context.Context, agent *Agent, dir string, verifier selfupdate.Verifier) error {
	spool, err := os.OpenRoot(dir)
	if errors.Is(err, fs.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	defer spool.Close()
	wire, err := readSpooled(spool, spoolStep, trust.MaxEnvelopeBytes)
	if errors.Is(err, fs.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	command, expires, err := VerifyStepCommand(wire, agent.Cell, agent.Unit, agent.Leaders, agent.now())
	if err != nil {
		return nil
	}
	if verifier != nil {
		agent.Fetch = spoolFetcher{spool: spool, verifier: verifier, now: agent.now}
	}
	data, err := json.Marshal(agent.handle(ctx, command, expires))
	if err != nil {
		return err
	}
	return writeFileAtomic(filepath.Join(agent.Layout.Root, ReplyFile(agent.SystemdUnit)), data, 0o644)
}

func openSpooled(spool *os.Root, name string) (*os.File, error) {
	file, err := spool.OpenFile(name, os.O_RDONLY|syscall.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	if info, err := file.Stat(); err != nil || !info.Mode().IsRegular() {
		file.Close()
		return nil, fmt.Errorf("%w: spooled %s is not a regular file", ErrInvalid, name)
	}
	return file, nil
}

func readSpooled(spool *os.Root, name string, limit int64) ([]byte, error) {
	file, err := openSpooled(spool, name)
	if err != nil {
		return nil, err
	}
	defer file.Close()
	data, err := io.ReadAll(io.LimitReader(file, limit+1))
	if err == nil && int64(len(data)) > limit {
		err = fmt.Errorf("%w: spooled %s is too large", ErrInvalid, name)
	}
	return data, err
}

// writeFileAtomic replaces path with data through a temporary file in the
// same directory.
func writeFileAtomic(path string, data []byte, mode os.FileMode) error {
	file, err := os.CreateTemp(filepath.Dir(path), "."+filepath.Base(path)+"-")
	if err != nil {
		return err
	}
	defer os.Remove(file.Name())
	defer file.Close()
	if err := file.Chmod(mode); err != nil {
		return err
	}
	if _, err := file.Write(data); err != nil {
		return err
	}
	if err := file.Sync(); err != nil {
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	return os.Rename(file.Name(), path)
}

func (command StepCommand) validate() error {
	if command.Schema != StepSchema || !unitRE.MatchString(command.Cell) || !entityid.Valid(command.RolloutID) ||
		command.Kind != rollout.KindController && command.Kind != rollout.KindHost || !unitRE.MatchString(command.Unit) ||
		!entityid.Valid(command.OperationID) || command.Action != StepPrepare && command.Action != StepRollback ||
		!digestRE.MatchString(command.Digest) || command.Epoch == 0 || command.ProofWindowSeconds <= 0 ||
		len(command.Receipt) > maxReleaseWire || len(command.Delegation) > maxReleaseWire ||
		len(command.Delegation) > 0 && len(command.Receipt) == 0 ||
		!digestRE.MatchString(command.Replaces) || command.Replaces == command.Digest {
		return fmt.Errorf("%w: step command", ErrInvalid)
	}
	return nil
}

// stepScope binds the signature to one operation, action and unit.
func stepScope(command StepCommand) trust.Scope {
	return trust.Scope{Domain: StepDomain, DeploymentID: command.OperationID, Cell: command.Cell,
		Environment: stepEnvironment, Role: string(command.Action), Slot: command.Unit}
}

// SignStepCommand signs command with the leader's controller key. The
// signature expires at deadline, or StepLifetime after now when that is
// sooner or deadline is zero: an agent never acts on a step after the phase
// deadline the leader enforces for it.
func SignStepCommand(command StepCommand, key ed25519.PrivateKey, now, deadline time.Time) ([]byte, error) {
	if err := command.validate(); err != nil {
		return nil, err
	}
	expires := now.Add(StepLifetime)
	if !deadline.IsZero() && deadline.Before(expires) {
		expires = deadline
	}
	if !expires.After(now) {
		return nil, fmt.Errorf("%w: step deadline has passed", ErrInvalid)
	}
	payload, err := trust.EncodePayload(command)
	if err != nil {
		return nil, err
	}
	envelope, err := trust.Sign(payload, stepScope(command), now, expires, key)
	if err != nil {
		return nil, err
	}
	return trust.EncodeEnvelope(envelope)
}

// VerifyStepCommand accepts a current command for exactly this cell and
// unit, signed by one of the controller keys. It also returns when the
// signature expires: the agent must not act on the command after that.
func VerifyStepCommand(wire []byte, cell, unit string, keys trust.Keyring, now time.Time) (StepCommand, time.Time, error) {
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return StepCommand{}, time.Time{}, err
	}
	scope := envelope.Scope
	if scope.Domain != StepDomain || scope.Cell != cell || scope.Slot != unit || scope.Environment != stepEnvironment ||
		scope.Role != string(StepPrepare) && scope.Role != string(StepRollback) {
		return StepCommand{}, time.Time{}, trust.ErrScopeMismatch
	}
	payload, err := trust.VerifyCurrent(envelope, scope, keys, now, trust.Policy{MaxLifetime: StepLifetime, ClockSkew: stepClockSkew})
	if err != nil {
		return StepCommand{}, time.Time{}, err
	}
	var command StepCommand
	if err := protocol.DecodeStrict(payload, &command, trust.MaxPayloadBytes); err != nil {
		return StepCommand{}, time.Time{}, err
	}
	if err := command.validate(); err != nil {
		return StepCommand{}, time.Time{}, err
	}
	if stepScope(command) != scope {
		return StepCommand{}, time.Time{}, trust.ErrScopeMismatch
	}
	return command, envelope.ExpiresAt, nil
}

func (a *Agent) now() time.Time {
	if a.Now != nil {
		return a.Now().UTC()
	}
	return time.Now().UTC()
}

// Handle verifies and applies one step and returns the reply.
func (a *Agent) Handle(ctx context.Context, wire []byte) StepReply {
	command, expires, err := VerifyStepCommand(wire, a.Cell, a.Unit, a.Leaders, a.now())
	if err != nil {
		return StepReply{Unit: a.Unit, Outcome: OutcomeRefused, Reason: "step command did not verify"}
	}
	return a.handle(ctx, command, expires)
}

// handle applies one verified command that expires at expires.
func (a *Agent) handle(ctx context.Context, command StepCommand, expires time.Time) StepReply {
	reply := StepReply{OperationID: command.OperationID, Unit: a.Unit, Epoch: command.Epoch}
	a.mu.Lock()
	defer a.mu.Unlock()
	window := max(selfupdate.MinProofWindow, min(selfupdate.MaxProofWindow,
		time.Duration(command.ProofWindowSeconds)*time.Second))
	// Nothing, staging included, outlives the signed command.
	stepCtx, cancel := context.WithDeadline(ctx, expires)
	defer cancel()
	reply.Outcome, reply.Reason = a.apply(stepCtx, command, expires, window)
	return reply
}

// apply fences the step by its authority epoch, which the release root
// records durably: an older leader's step is refused even after this agent
// restarted. The restart obligation is recorded before the release changes
// and cleared only by the unit's next start, so any interruption leaves the
// watchdog (and a retry by a new agent) a restart to finish.
func (a *Agent) apply(ctx context.Context, command StepCommand, expires time.Time, window time.Duration) (StepOutcome, string) {
	if outcome, reason := a.locked(func() (StepOutcome, string) {
		if a.Guard != nil {
			if err := a.Guard(ctx, command); err != nil {
				return OutcomeRefused, err.Error()
			}
		}
		return a.admit(command)
	}); outcome != "" {
		return outcome, reason
	}
	if outcome, reason := a.ensureStaged(ctx, command); outcome != "" {
		return outcome, reason
	}
	outcome, reason := a.locked(func() (StepOutcome, string) {
		// Re-checked under the lock, immediately before the selection
		// changes: waiting for the lock or a staging download must not
		// let an expired command act.
		if !a.now().Before(expires) {
			return OutcomeRetry, "step command expired before it could be applied"
		}
		if a.Guard != nil {
			if err := a.Guard(ctx, command); err != nil {
				return OutcomeRefused, err.Error()
			}
		}
		if outcome, reason := a.admit(command); outcome != "" {
			return outcome, reason
		}
		if command.Action == StepRollback {
			return a.restore(command)
		}
		return a.activate(command, window)
	})
	if !outcome.Accepted() {
		return outcome, reason
	}
	owed, err := a.owed()
	if err != nil {
		return OutcomeRetry, "restart obligation is unreadable"
	}
	if !owed || a.served == command.OperationID && outcome != OutcomeActivated {
		return outcome, reason
	}
	if err := a.restart(ctx); err != nil {
		slog.WarnContext(ctx, "rollout agent could not restart its unit", "component", "rollout", "unit", a.Unit, "error", err)
		return OutcomeRetry, "unit restart failed"
	}
	a.served = command.OperationID
	return outcome, reason
}

// admit records the step's epoch, refusing an older one. The caller holds
// Layout.Lock.
func (a *Agent) admit(command StepCommand) (StepOutcome, string) {
	if err := a.Layout.AdmitEpoch(command.Epoch); errors.Is(err, selfupdate.ErrStaleEpoch) {
		return OutcomeRefused, "step is from an older authority epoch"
	} else if err != nil {
		return OutcomeRetry, "authority epoch record is unreadable"
	}
	return "", ""
}

func (a *Agent) owed() (bool, error) {
	unlock, err := a.Layout.Lock()
	if err != nil {
		return false, err
	}
	defer unlock()
	return a.Layout.RestartPending(a.SystemdUnit)
}

// locked runs step under Layout.Lock.
func (a *Agent) locked(step func() (StepOutcome, string)) (StepOutcome, string) {
	unlock, err := a.Layout.Lock()
	if err != nil {
		return OutcomeRetry, "release root is locked"
	}
	defer unlock()
	return step()
}

// ensureStaged restages a release that is not in the release root (a
// rollback target pruned after its activation settled) from the step's
// signed receipt. It runs unlocked, like selfupdate's own fetch.
func (a *Agent) ensureStaged(ctx context.Context, command StepCommand) (StepOutcome, string) {
	err := a.Layout.VerifyRelease(command.Digest)
	switch {
	case err == nil:
		return "", ""
	case !errors.Is(err, fs.ErrNotExist):
		return OutcomeRefused, "staged release does not verify"
	case a.Fetch == nil || len(command.Receipt) == 0:
		return OutcomeRefused, "release is not staged and cannot be restaged"
	}
	staged, err := a.Fetch.Fetch(ctx, a.Layout, command.Receipt, command.Delegation)
	if err != nil {
		slog.WarnContext(ctx, "rollout agent could not stage a release", "component", "rollout", "unit", a.Unit,
			"digest", command.Digest, "error", err)
		return OutcomeRetry, "release staging failed"
	}
	if staged != command.Digest {
		return OutcomeRefused, "the step's receipt names another release"
	}
	return "", ""
}

// activate moves the unit forward through a proof-gated A/B activation.
// A retry of a matching pending activation goes through Activate again, so
// its gates rerun and an interrupted link flip is repaired. The caller
// holds Layout.Lock.
func (a *Agent) activate(command StepCommand, window time.Duration) (StepOutcome, string) {
	digest := command.Digest
	pending, exists, err := a.Layout.Pending()
	if err != nil {
		return OutcomeRetry, "activation state is unreadable"
	}
	if exists && (pending.Target != digest || pending.Unit != a.SystemdUnit || pending.Previous != command.Replaces) {
		// The watchdog resolves the other activation by its deadline.
		return OutcomeRetry, "another activation is pending"
	}
	if !exists {
		if current, err := a.Layout.Current(); err != nil {
			return OutcomeRetry, "current release is unreadable"
		} else if current == digest {
			return OutcomeCurrent, ""
		} else if current != command.Replaces {
			// A forward step only moves the unit off the rollout's
			// predecessor: a replayed step of an earlier rollout never
			// undoes the update that settled after it.
			return OutcomeRefused, "the unit does not run the step's predecessor release"
		}
		// Owed before the link moves, so an interruption after it never
		// leaves the old process running until the watchdog rejects a
		// release that never started.
		if err := a.Layout.MarkRestartPending(a.SystemdUnit); err != nil {
			return OutcomeRetry, "restart obligation could not be recorded"
		}
	}
	if _, err := selfupdate.Activate(a.Layout, digest, a.SystemdUnit, a.now(), window); err != nil {
		if !exists {
			// Nothing to restart unless the activation record was written;
			// an unreadable activation state keeps the obligation.
			if _, recorded, pendingErr := a.Layout.Pending(); pendingErr == nil && !recorded {
				_ = a.Layout.ClearRestartPending(a.SystemdUnit)
			}
		}
		if errors.Is(err, selfupdate.ErrKnownBad) {
			return OutcomeRefused, "release is known bad on this node"
		}
		slog.Warn("rollout agent could not activate a release", "component", "rollout", "unit", a.Unit,
			"digest", digest, "error", err)
		return OutcomeRetry, "activation failed"
	}
	if exists {
		return OutcomePending, ""
	}
	return OutcomeActivated, ""
}

func (layout Layout) epochPath() string { return filepath.Join(layout.Root, epochFile) }

// AcceptedEpoch returns the newest accepted authority epoch, zero when none.
// The caller holds Lock.
func (layout Layout) AcceptedEpoch() (uint64, error) {
	if err := layout.checkOwned(layout.epochPath(), false); errors.Is(err, os.ErrNotExist) {
		return 0, nil
	} else if err != nil {
		return 0, err
	}
	data, err := readBounded(layout.epochPath(), 64)
	if err != nil {
		return 0, err
	}
	epoch, err := strconv.ParseUint(strings.TrimSpace(string(data)), 10, 64)
	if err != nil || epoch == 0 {
		return 0, fmt.Errorf("%w: accepted authority epoch", ErrInvalid)
	}
	return epoch, nil
}

// AdmitEpoch durably records epoch as accepted before the caller acts on
// an order from it, and refuses an epoch older than one already accepted.
// The caller holds Lock across AdmitEpoch and the effects it fences.
func (layout Layout) AdmitEpoch(epoch uint64) error {
	if epoch == 0 {
		return fmt.Errorf("%w: authority epoch", ErrInvalid)
	}
	accepted, err := layout.AcceptedEpoch()
	if err != nil {
		return err
	}
	switch {
	case epoch < accepted:
		return ErrStaleEpoch
	case epoch == accepted:
		return nil
	}
	if err := layout.ensureDirs(); err != nil {
		return err
	}
	return writeFileAtomic(layout.epochPath(), fmt.Appendf(nil, "%d\n", epoch), 0o644)
}

func execLines(t *testing.T, path, key string) []string {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var values []string
	for line := range strings.SplitSeq(string(data), "\n") {
		if name, value, ok := strings.Cut(line, "="); ok && !strings.HasPrefix(line, "#") && name == key {
			values = append(values, value)
		}
	}
	return values
}

func checkCurrentReleaseDropin(t *testing.T, unit, command, dropin string, install func(string) (bool, error)) {
	t.Helper()
	deploy := filepath.Join("..", "..", "..", "deploy", "systemd")
	base := execLines(t, filepath.Join(deploy, unit), "ExecStart")
	if len(base) != 1 || !strings.HasPrefix(base[0], selfupdate.DefaultBakedBinary+" "+command) {
		t.Fatalf("%s ExecStart = %q", unit, base)
	}
	args := strings.TrimPrefix(base[0], selfupdate.DefaultBakedBinary)
	path := filepath.Join(t.TempDir(), "60-selfupdate.conf")
	if err := os.WriteFile(path, []byte(dropin), 0o644); err != nil {
		t.Fatal(err)
	}
	got := execLines(t, path, "ExecStart")
	if len(got) != 2 || got[0] != "" || !strings.HasPrefix(got[1], "/bin/sh -c '") || !strings.HasSuffix(got[1], args+"'") {
		t.Fatalf("drop-in ExecStart = %q, want reset then a shell running %q", got, args)
	}
	// Run the shell line as systemd would ($$ is a literal $), with the
	// release and baked paths moved into a scratch root.
	temp := t.TempDir()
	current := filepath.Join(temp, "current", selfupdate.BinaryName)
	baked := filepath.Join(temp, "baked")
	script := strings.TrimSuffix(strings.TrimPrefix(got[1], "/bin/sh -c '"), "'")
	script = strings.NewReplacer("$$", "$", selfupdate.NewLayout(selfupdate.DefaultRoot).CurrentExecutable(), current,
		selfupdate.DefaultBakedBinary, baked).Replace(script)
	for _, path := range []string{current, baked} {
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(path, []byte("#!/bin/sh\necho "+filepath.Base(filepath.Dir(path))+" \"$@\"\n"), 0o755); err != nil {
			t.Fatal(err)
		}
	}
	for i, want := range []string{"current", filepath.Base(temp)} {
		if i == 1 {
			if err := os.Remove(current); err != nil {
				t.Fatal(err)
			}
		}
		out, err := exec.Command("/bin/sh", "-c", script).Output()
		if err != nil || !strings.HasPrefix(string(out), want+args) {
			t.Fatalf("drop-in ran %q, %v; want %s%s", out, err, want, args)
		}
	}
	// prepare's installer: nothing without the unit, then the drop-in once.
	systemd := t.TempDir()
	if installed, err := install(systemd); err != nil || installed {
		t.Fatalf("installed without %s: %v, %v", unit, installed, err)
	}
	if err := os.WriteFile(filepath.Join(systemd, unit), []byte("[Service]\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	for _, want := range []bool{true, false} {
		if installed, err := install(systemd); err != nil || installed != want {
			t.Fatalf("install %s = %v, %v, want %v", unit, installed, err, want)
		}
	}
	if data, err := os.ReadFile(filepath.Join(systemd, unit+".d", "60-selfupdate.conf")); err != nil || string(data) != dropin {
		t.Fatalf("installed drop-in: %v", err)
	}
}

const HostSetupDropin = `# Binary-only A/B self-update (docs/continuous-delivery.md), installed by the
# image and by selfupdate prepare on a host whose image predates it.
[Service]
# First enrollment shares the private NetBird transaction lock with the worker.
StateDirectory=terrascale-orchestrator/netbird-managed
StateDirectoryMode=0700
# host-setup runs the current release, the one the host agent runs, so an
# enrollment change ships with a rollout; the image-baked binary runs it
# until prepare seeds a current release.
ExecStart=
ExecStart=/bin/sh -c 'b=/var/lib/terrascale-orchestrator/current/terrascale-orchestrator; [ -x "$$b" ] || b=/usr/local/bin/terrascale-orchestrator; exec "$$b" host-setup --public-config /etc/terrascale-orchestrator/host-enrollment-public.json --output-root /etc/terrascale-orchestrator'
# The enrollment identity and credentials live in memory and outlive this
# oneshot for the host agent; host-setup restores the identity from Vault
# after a reboot (TS-745).
RuntimeDirectory=terrascale-orchestrator-host-credentials
RuntimeDirectoryMode=0700
RuntimeDirectoryPreserve=yes
`

// BootstrapUnit admits a controller install before the controller starts.
const BootstrapUnit = "terrascale-orchestrator-bootstrap.service"

// BootstrapDropin makes bootstrap admission run the current release, the one
// the controller runs, so a controller.json a newer release installed (a
// material generation, TS-668) is admitted at boot: the image-baked binary may
// refuse its members. The baked binary runs it until prepare seeds a current
// release. Only prepare installs it; the image does not carry it.
const BootstrapDropin = `# Binary-only A/B self-update (docs/continuous-delivery.md), installed by
# selfupdate prepare.
[Service]
# Bootstrap admission runs the current release, the one the controller runs,
# so a config a newer release installed is admitted at boot; the image-baked
# binary runs it until prepare seeds a current release.
ExecStart=
ExecStart=/bin/sh -c 'b=/var/lib/terrascale-orchestrator/current/terrascale-orchestrator; [ -x "$$b" ] || b=/usr/local/bin/terrascale-orchestrator; exec "$$b" bootstrap-controller --config /etc/terrascale-orchestrator/controller.json'
# The credential directory is memory only: the same release rebuilds it from
# Vault first (TS-745), and admission waits until it can. Only a rolled-back
# release that lacks the command skips it.
ExecStartPre=
ExecStartPre=+/bin/sh -c 'b=/var/lib/terrascale-orchestrator/current/terrascale-orchestrator; [ -x "$$b" ] || b=/usr/local/bin/terrascale-orchestrator; "$$b" --help 2>/dev/null | grep -q restore-controller-material || exit 0; exec "$$b" restore-controller-material'
`

// ControllerInstallUnit installs the root-signed controller configuration before admission.
const ControllerInstallUnit = "terrascale-orchestrator-controller-install.service"

// ControllerInstallDropin makes controller config installation run the current
// release, the one the controller runs, so an identity or config a newer
// release installed survives a reboot: the image-baked binary may refuse it.
// The baked binary runs it until prepare seeds a current release. Only prepare
// installs it; the image does not carry it.
const ControllerInstallDropin = `# Binary-only A/B self-update (docs/continuous-delivery.md), installed by
# selfupdate prepare.
[Service]
# Config installation runs the current release, the one the controller runs,
# so an identity or config a newer release installed survives a reboot; the
# image-baked binary runs it until prepare seeds a current release.
ExecStart=
ExecStart=/bin/sh -c 'b=/var/lib/terrascale-orchestrator/current/terrascale-orchestrator; [ -x "$$b" ] || b=/usr/local/bin/terrascale-orchestrator; exec "$$b" install-controller-config'
`

// InstallHostSetupDropin writes HostSetupDropin below systemdDir on a host,
// one with the host-setup unit, and reports whether it changed it. systemd
// reads it from the next boot.
func InstallHostSetupDropin(systemdDir string) (bool, error) {
	return installDropin(systemdDir, HostSetupUnit, "60-selfupdate.conf", HostSetupDropin)
}

// InstallBootstrapDropin writes BootstrapDropin below systemdDir on a
// controller, one with the bootstrap unit, and reports whether it changed it.
// systemd reads it from the next boot.
func InstallBootstrapDropin(systemdDir string) (bool, error) {
	return installDropin(systemdDir, BootstrapUnit, "60-selfupdate.conf", BootstrapDropin)
}

// InstallControllerInstallDropin writes ControllerInstallDropin below systemdDir
// on a controller, one with the controller-install unit, and reports whether it
// changed it. systemd reads it from the next boot.
func InstallControllerInstallDropin(systemdDir string) (bool, error) {
	return installDropin(systemdDir, ControllerInstallUnit, "60-selfupdate.conf", ControllerInstallDropin)
}

func installDropin(systemdDir, unit, file, dropin string) (bool, error) {
	if _, err := os.Stat(filepath.Join(systemdDir, unit)); errors.Is(err, os.ErrNotExist) {
		return false, nil
	} else if err != nil {
		return false, err
	}
	dir := filepath.Join(systemdDir, unit+".d")
	path := filepath.Join(dir, file)
	if current, err := os.ReadFile(path); err == nil && string(current) == dropin {
		return false, nil
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return false, err
	}
	return true, writeFileAtomic(path, []byte(dropin), 0o644)
}

func InstallWatchdogLoggingDropin(systemdDir string) (bool, error) {
	return installDropin(systemdDir, WatchdogUnit, "10-logging.conf", WatchdogLoggingDropin)
}
